    faq_a_glib_friends: "Ein Thema für Freundschaften und Herzlichkeit im Umgang mit Menschen: neue Freundschaften schließen, wirklich zuhören, eine alte Freundschaft wiederbeleben, Freunde zu sich einladen, jeden Tag ein freundliches Wort sowie ein Lächeln und ein Hallo. Zwei kleine Ideen darin stammen aus Dale Carnegies Klassiker „Wie man Freunde gewinnt“ – sich Namen merken und sich ehrlich für andere interessieren. Tippe auf der Buchkarte auf „+ Leseecke“, um das Buch in die Leseecke zu legen, unter „Zu lesen“ – danach verschwindet die Karte aus den Zielen.",
