    bag_examples_v2_toast: "🎁 Neue Beispiele in deiner Tasche: Geschenkideen, eine Packliste fürs Hotel und eine für den Flug ✨",
    faq_a_bag_examples_list: "Eine neue Tasche kommt mit Beispielen, die du wie alles andere ändern oder löschen kannst: Zuhause (Einkauf, Rezepte, Essen dieser Woche), Familie (kleine Momente, eine Liste für die Geburtstagsfeier, Kurse und Aktivitäten), Ideen (Ideen fürs Wochenende, Geschenkideen nach Kategorie und was du mit gespartem Geld machst) und Reisen (Orte, an die du willst, Packliste für die Reise, Packliste fürs Hotel und eine Liste für den Flug ins Ausland). Eine Tasche, die es schon gab, bekommt die neuesten einmal dazu, in ihre eigenen Fächer.",
    faq_q_bag_examples_list: "Welche Beispiele gibt es in Meine Tasche?",
    faq_a_nm_me1_guide: "Sky – deine Figur in New Me, in seiner ersten Form (Sky 1). Beim ersten Mal, direkt nach dem Beitritt, öffnet sich ein Portal aus Licht, ringsum funkelt es, Sky fliegt heraus, erklärt mit wenigen Fingertipps, was dich erwartet, und bleibt dann bei jeder Frage an deiner Seite: Während die Mahlzeiten gewählt werden, schreibt er mit dir in sein Buch, und ein Tipp auf seinen Ratschlag zeigt einen neuen. Am Ende feiert Sky mit dir und nimmt dich mit auf eine kurze Tour – und wenn die Tour vorbei ist, hat er noch einen kleinen Moment mit dir. Wenn du mittendrin gehst – bei den Fragen oder in der Tour –, freut sich Sky beim nächsten Mal, dich zu sehen, und fragt, ob es an derselben Stelle weitergehen soll.",
    faq_q_nm_me1_guide: "Wer begleitet dich beim Einstieg in New Me?",
    nm_m1_day_text: "Jeden Tag – ein ✓ bei jeder Mahlzeit, und ich zähle alles für dich.",
