    nm_m1_hi_title: "Hallo! Ich bin Sky",
    nm_m1_joy_btn: "Eine kurze Tour",
    nm_m1_joy_text: "Dein Menü wartet, und die magische Welt erwacht schon.",
    nm_m1_joy_title: "Juhu! Alles ist bereit",
    nm_m1_magic_text: "Und jeder echte Schritt nach vorn öffnet dir weitere Orte in der magischen Welt",
    nm_m1_menu_text: "Gemeinsam stellen wir ein Menü zusammen, das genau zu dir passt: Essen, das du liebst, zu Zeiten, die dir passen.",
    nm_m1_portal: "Eine neue Welt öffnet sich",
    nm_m1_q_about: "Schön, dich kennenzulernen!",
    nm_m1_q_agree: "Bevor wir anfangen – ein paar wichtige Worte",
    nm_m1_q_letter: "Ein paar Worte an dein zukünftiges Ich? Ich bewahre sie sicher für dich auf",
    nm_m1_q_menu: "Lass uns die Träume gemeinsam aufschreiben – und gemeinsam wahr machen",
    nm_m1_q_plan: "Du kannst jederzeit wechseln – hier gibt es keine falsche Wahl.",
    nm_m1_q_times: "Deine Zeiten sind auch meine Zeiten",
    nm_m1_ready_text: "Zuerst ein paar kleine Fragen – dann wählen wir zusammen die Mahlzeiten aus.",
    nm_m1_skip: "Überspringen",
    nm_m1_tip_ai: "Ein Essen, das nicht auf der Liste steht? Später kannst du es unter „Tauschen“ in eigenen Worten aufschreiben – und die KI rechnet es aus. Und jetzt wählen wir zusammen aus, was du jeden Tag isst.",
    nm_m1_tip_love: "Und wenn du etwas nicht magst – du kannst es jederzeit mit der KI tauschen. Egal, welches Essen – wenn du es liebst, bleibt es auf dem Menü.",
    nm_m1_tip_rice: "Reis mag ich am allerliebsten – er wird meine Basis, also wähle ich ihn. Ich empfehle, bei dem zu bleiben, was vertraut ist und schmeckt.",
    faq_a_shop_basics: "Wenn die Einkaufsliste ganz leer ist – zum Beispiel ganz am Anfang –, erscheint eine Basisliste für den Anfang: Milch, Brot, Eier und mehr. Ein Tippen auf einen Artikel fügt ihn der Liste hinzu, und „Alle hinzufügen“ fügt alles auf einmal hinzu. Sobald etwas auf der Liste steht, verschwindet die Basisliste.",
    faq_q_shop_basics: "Was ist die Basisliste in einer leeren Einkaufsliste?",
