    room_genie_again_no: "Jetzt nicht",
    room_genie_again_no_msg: "Dann ist es Zeit, die Ziele zu erreichen, die du dir schon gesetzt hast. Wenn du beim nächsten ankommst – wartet dort etwas auf dich ✨",
    room_genie_again_q: "Schon wieder da? ✨ Möchtest du noch etwas anderes in deinem Leben verändern?",
    room_genie_again_yes: "Ja",
    room_genie_bye: "Bis bald",
    room_genie_rest: "Der Waldgeist ruht sich jetzt aus – komm morgen wieder ✨",
    faq_a_shop_holidays: "Tippe in der Einkaufsliste auf das Geschenk: Die Feiertage deines Landes (aus den Einstellungen) erscheinen der Reihe nach, mit ihren Daten – jedes Jahr automatisch berechnet. Tippe auf einen Feiertag, um eine fertige Liste mit dem zu sehen, was man dafür kauft; alles ist ausgewählt (außer dem, was schon auf deiner Liste steht), entferne das Häkchen bei allem, was du nicht brauchst, und tippe auf „Zur Liste hinzufügen“. Zwei Wochen vor einem Feiertag erscheint oben in der Liste eine kleine Karte; ✕ blendet sie bis zum nächsten Feiertag aus.",
    faq_q_shop_holidays: "Wie funktioniert „Was fürs Fest kaufen“?",
