    shop_hol_items_title: "{holiday} – was kaufen?",
    shop_hol_not_now: "Nicht jetzt",
    faq_a_shop_delivery: "Tippe in der Einkaufsliste auf den Lastwagen: Wähle, was in der Lieferung ist (alles ist ausgewählt), wann sie kommt – heute, morgen oder an einem anderen Tag – und zu welcher Zeit (Vormittag, Nachmittag, Abend oder „Andere…“ für deine eigenen Zeiten). Diese Artikel wandern auf eine Karte „Unterwegs“ oben in der Liste, mit dem Tag und den Uhrzeiten. Wenn der Tag da ist, erscheint „Ist die Lieferung angekommen?“ in Mein Tag (und auf der Karte steht „Angekommen?“). Ist alles angekommen, wandern sie zu „Wieder kaufen“. Fehlt etwas, tippe auf das, was nicht angekommen ist, und es kommt direkt zurück auf die Liste.",
    faq_a_shop_departments: "Die Liste sortiert sich selbst nach den Abteilungen im Supermarkt – Obst & Gemüse, Brot, Milchprodukte & Eier, Fleisch & Fisch, Vorrat, Tiefkühl, Getränke, Snacks, Haushalt, Drogerie, Baby und Tierbedarf –, damit du die Gänge der Reihe nach abläufst. Die Abteilung wird am Namen des Artikels erkannt. Ist ein Artikel am falschen Platz gelandet, tippe darauf und wähle seine Abteilung oder „Sonstiges…“, um selbst eine einzutragen.",
    faq_a_shop_share_qty: "Ja. Neben jedem Artikel fügt + eins hinzu (×2, ×3…) und − nimmt eins weg. Der Teilen-Button oben in der Einkaufsliste schickt die ganze Liste, ordentlich nach Abteilungen sortiert, per WhatsApp, per E-Mail oder als Kopie.",
    faq_a_shop_two_buttons: "Beide bedeuten „gekauft“. ✕ ist für etwas, das du einmal kaufst – es verschwindet von der Liste (und wartet im Archiv 🗑️, falls es ein Versehen war). ↺ ist für Dinge, die du immer wieder kaufst – sie verschwinden von der Liste und warten in „Wieder kaufen“: Das öffnet der kleine ↺-Button neben dem Papierkorb unten in der Liste, und ein Tippen dort setzt einen Artikel zurück auf die Liste. Unter „Bearbeiten“ darin kannst du einen Artikel herausnehmen. Wenn du etwas hinzufügst, erscheint, was du schon einmal gekauft hast, als Vorschlag, und steht es schon auf der Liste, wird es einfach zu ×2 statt zu einer zweiten Zeile.",
    faq_q_shop_delivery: "Wie funktioniert „Ich habe eine Lieferung bestellt“?",
