    nm_demo_title: "So funktioniert ein Tausch",
    faq_a_new_me_challenge_journal: "Wenn eine Challenge endet – eine große, eine Mini-Challenge oder die Challenge der Woche –, zeigt die Feier einen Button 📝 Wie lief's?, der eine Seite im Challenge-Tagebuch öffnet: wie es sich angefühlt hat (fünf Gesichter), was geholfen hat, was schwer war und was ich mitnehme – nichts davon ist Pflicht, und es kann auch auf später warten. Das Tagebuch ist ein Diamant im Zauberrucksack: jede beendete Challenge mit Datum und dem, was geschrieben wurde, die neueste zuerst – tippe auf eine, um sie zu lesen, zu bearbeiten oder zu teilen (geteilt wird nur, was auf der Seite steht). Eine beendete Challenge bekommt außerdem eine Medaille bei den Erfolgen, unter „Meine geschafften Challenges“. Das Challenge-Tagebuch ist vom normalen Tagebuch getrennt.",
    faq_q_new_me_challenge_journal: "Was ist das Challenge-Tagebuch?",
    nm_badges_challenges: "Meine geschafften Challenges",
    nm_chj_empty: "Hier erscheinen die Challenges, die du abschließt",
