    nm_chj_q: "Wie lief die Challenge?",
    nm_chj_reflect_btn: "Wie lief's?",
    nm_chj_save: "Im Challenge-Tagebuch speichern",
    nm_chj_saved: "Im Challenge-Tagebuch gespeichert",
    nm_chj_share_text: "Ich habe in New Me eine Challenge geschafft ✨",
    nm_chj_take: "Was nehme ich mit?",
    nm_chj_title: "Challenge-Tagebuch",
    nm_chj_write: "Aufschreiben, wie es lief",
    nm_swap_time: "Uhrzeit",
    faq_a_ai_reminder_in_text: "Ja – schreibe sie einfach zusammen mit der Aufgabe, zum Beispiel „morgen um 17:00 das Paket abholen, mit einer Erinnerung eine Stunde vorher“. Die Erinnerung wird direkt bei der Aufgabe gespeichert: eine Stunde vorher, eine halbe Stunde, einen Tag vorher und so weiter, und „erinnere mich“ ohne Zeitangabe heißt 10 Minuten vorher. Eine im Text geschriebene Erinnerung hat Vorrang vor dem Erinnerungsfeld im selben Fenster.",
    faq_q_ai_reminder_in_text: "Kann ich den KI-Assistenten in derselben Anfrage um eine Erinnerung bitten?",
    myday_meals_all_done: "Alle Mahlzeiten von heute sind abgehakt 🍽️",
    nm_tour_week_text: "Eine kleine Challenge für die Woche. ✓ jeden Tag – am Ende ein Schlüssel.",
    books_home_chip: "{title} · S. {page}",
    books_home_of: "von {total}",
    books_home_off_toast: "Das Buch ist nicht mehr auf dem Startbildschirm",
    books_home_on_toast: "Das Buch ist auf dem Startbildschirm 📖",
    books_home_pin: "Auf dem Startbildschirm",
    books_home_q: "Auf welcher Seite bin ich?",
    books_home_save: "Speichern",
    faq_a_books_home_chip: "Ja. In der Leseecke tippst du auf der Karte eines Buches, das du gerade liest, auf 📌 Auf dem Startbildschirm. Unter der Begrüßung auf dem Startbildschirm erscheint ein kleiner Button mit dem Buch und der Seite – tippe darauf, gib die neue Seitenzahl ein und speichere, und der Fortschritt wird festgehalten (auch in der Leseecke). Ein erneutes Antippen von 📌 entfernt ihn wieder. Es können mehrere Bücher zugleich dort sein – für jedes ein Button –, und auf allen Geräten gleich.",
    faq_a_new_me_week_challenge: "Eine kleine Challenge für eine Woche, die du selbst auswählst. Im Flur liegt eine große Karte: „Woran möchtest du diese Woche arbeiten?“ – tippe darauf, wähle einen Bereich (mit mir selbst, mit anderen, lernen und wachsen, Ruhe, kleine mutige Schritte, Zuhause und Routine) und eine Challenge und lege fest, wann sie beginnt. Dieselben Challenges findest du auch im Challenge-Bildschirm unter 🌱 Persönliche Entwicklung. Jeden Tag wird auf der Karte ein ✓ gesetzt (ein freier Tag pro Woche), und jede abgeschlossene Woche bringt einen neuen Schlüssel für die geheime Welt. „2 Seiten am Tag lesen“ wird von selbst abgehakt, anhand der Seiten, die in der Leseecke eingetragen werden. Wenn die Woche endet, fügt 📌 Als tägliche Aufgabe behalten sie zur gewählten Uhrzeit zu Meine Routine hinzu, mit einem ✓ jeden Tag. Es läuft immer nur eine Challenge der Woche; die großen und die Mini-Challenges laufen daneben weiter.",
    faq_a_room_genie: "Auf der Veranda am Meer holt ein Antippen von Aladins Lampe den Waldgeist hervor – und ein Gespräch beginnt: Was ist dein Wunsch (was möchtest du in deinem Leben verändern), wie wird es sich anfühlen, wenn er in Erfüllung geht, was ist auf dem Weg schwer und wie lässt sich die Situation von jetzt in etwas Gutes verwandeln. Dann, wie lange es ungefähr dauern wird, ein kleiner erster Schritt und zwei weitere, und ein „Wenn… dann…“ für die Momente, in denen es schwer wird. Am Ende erscheint der ganze Wunsch Schritt für Schritt, und er kann zu einem Ziel in Meine Ziele werden (die Schritte werden zu Meilensteinen auf dem Weg, mit einem Datum nach der gewählten Dauer; dort lässt sich alles ändern) oder im Tagebuch gespeichert werden – und dann verabschiedet sich der Waldgeist. Es wird nichts gespeichert, wenn keins von beidem gewählt wird. Ab dem zweiten Besuch fragt der Waldgeist zuerst, ob du noch etwas anderes in deinem Leben verändern möchtest: Ja – dasselbe Gespräch; Jetzt nicht – eine Erinnerung, die schon gesetzten Ziele zu erreichen. Der Waldgeist kommt einmal am Tag heraus: Nachdem ein Wunsch gespeichert wurde (oder nach „Jetzt nicht“), ruht er bis morgen. Die Fragen folgen einer bekannten Methode, einen Wunsch in einen Plan zu verwandeln: Wunsch, Ergebnis, Hindernis und Plan.",
    faq_q_books_home_chip: "Kann ich mein Buch und die Seite auf dem Startbildschirm sehen?",
    faq_q_new_me_week_challenge: "Was ist die Challenge der Woche?",
    faq_q_room_genie: "Was macht der Geist der Lampe?",
