    room_drawer_aria: "Schränkchen",
    nm_me_choose: "Wählen",
    nm_me_on_screen: "Im Bild",
    faq_a_new_me_game: "In New Me bleiben die Spiel-Buttons immer an derselben Stelle – im Flur, im geheimen Zimmer und überall im Wald; nur das Bild in der Mitte wechselt. Oben: der Tag auf der Reise, Schlüssel, Serie und die Energie von heute (wie viel vom Plan schon gegessen wurde), und darunter die nächste Mission – die nächste Mahlzeit zu ihrer Uhrzeit (ein Tipp öffnet sie, mit ✓ Gegessen). An der Seite: der ganze Tag, Challenges und meine Reise, und daneben die Challenge der Woche – ihre 7 Tage und ein ✓ für heute. Unten: der Zauberrucksack (ganz New Me – Weltkarte, meine Reise, Einkaufsliste, Erfolge, Challenge-Tagebuch, Körpermaße, Fortschrittsfotos, Monatskalender, Tagestabelle, Erinnerungen, Menü als PDF und Einstellungen; er öffnet sich als eigener Bildschirm). Die Weltkarte, das Erste im Rucksack, zeigt alle Orte im Wald – tippe auf einen Ort, um dorthin zu gehen; an einem verschlossenen Ort steht, wie viele Schlüssel er braucht. Sky ist deine Figur auf dem Waldweg: Er startet als Sky 1, wächst nach ein paar Challenges (4 Schlüssel) zu Sky 2 heran und gegen Ende (9 Schlüssel) zu Sky 3 – mit einer Verwandlung, die man live sieht. Tippe auf Sky, um alle Stufen zu sehen – jede schon erreichte Stufe kann erneut gewählt werden, so kann eine frühere zurückkommen. Sky schwebt – zieh ihn mit dem Finger oder der Maus, und der Eingang, den er berührt, öffnet sich (bei einem verschlossenen steht, wie viele Schlüssel fehlen). Sky kommt auch mit in jeden Raum und an jeden Ort und schwebt dort, wo du ihn lässt: Zieh ihn irgendwohin, und zieh den leuchtenden Ring unter ihm, um ihn einmal ganz um sich selbst zu drehen; er schaut in die Richtung, in die er sich bewegt (am Computer: Die Pfeiltasten bewegen ihn, Q und E drehen ihn). Im Flur führt das kleine 🏠 unter der oberen Leiste zurück zum Startbildschirm; in jedem Raum und an jedem Ort führt der Button in derselben Ecke zurück in den Flur.",
    faq_q_new_me_game: "Wie funktionieren die Spiel-Buttons, die Weltkarte und Sky?",
