    room_magic_song_rec3: "Glöckchen am Wasserfall",
    faq_a_new_me_menu_build: "Zuerst fragt der Fragebogen, welche Mahlzeiten du wann isst (2 Mahlzeiten + ein Snack, 2 Mahlzeiten + ein leichtes Abendessen oder beides) und ob es abends noch etwas gibt – zu essen oder zu trinken, was und um wie viel Uhr. Bei „2 Mahlzeiten + ein Snack“ sind die Mahlzeiten Mittagessen (11:30) und Abendessen (19:00), mit dem Snack um 16:00. Dann erscheinen alle Vorschläge für diese Mahlzeiten. Wähle pro Mahlzeit bis zu 2 Favoriten – im Menü steht dann „dies oder das“. Bei manchen Vorschlägen (Pita & Aufstrich, Cornflakes mit Milch, etwas Leichtes) wählst du bis zu 3 Dinge, die du magst, jedes in seiner eigenen Portion, und im Menü steht „dies oder das oder jenes“; die Kalorien richten sich nach deiner Auswahl. Bei Kaffee und Getränken funktioniert es genauso. Jede Wahl wird ausgeglichen, sodass der Tag genau 1.300 oder 1.500 ergibt. Ändern kannst du das jederzeit: ⚙️ Einstellungen → 🍽️ Stell dein Menü zusammen, oder „Wähle bis zu 3, die du magst“ auf der Karte der Mahlzeit.",
    faq_q_new_me_menu_build: "Wie wird das New-Me-Menü zusammengestellt?",
