    faq_a_myday_water_toggle: "Ja. Das Wasserglas in 'Mein Tag' (mit + für ein weiteres Glas) ist standardmäßig sichtbar. Zum Ausblenden „Wasser in 'Mein Tag' anzeigen“ unter Einstellungen > Personalisierung & Kalender ausschalten. Es wird nichts gelöscht – das Wasser-Tracking läuft weiter, und beim Einschalten ist das Glas wieder da.",
    faq_q_myday_water_toggle: "Kann ich das Wasser in 'Mein Tag' ausblenden?",
    myday_water_toggle_label: "Wasser in 'Mein Tag' anzeigen",
    faq_a_routine_newme_sync: "Mit New Me hat das ⚙️ von Meine Routine einen Schalter „Mit New Me synchronisieren“. Eingeschaltet (Standard) erscheinen die heutigen New-Me-Mahlzeiten in Mein Tag und in Meine Routine – an der Stelle der Routine-Mahlzeiten, die ausgeblendet wurden. Ausgeschaltet verschwinden die New-Me-Mahlzeiten aus beiden, und die Routine ist wieder genau wie vorher. Nichts wird gelöscht – erneutes Einschalten bringt alles zurück und fragt, welche Routine-Mahlzeiten ausgeblendet werden sollen.",
    faq_q_routine_newme_sync: "Wie schalte ich die Synchronisierung von New Me mit Meine Routine und Mein Tag ein oder aus?",
    routine_newme_sync_label: "Mit New Me synchronisieren",
    routine_newme_sync_off_toast: "Synchronisierung aus – die New-Me-Mahlzeiten sind aus Mein Tag raus, und deine Routine ist wieder wie vorher",
