    theme_name_watercolor_wash: "Aquarell",
    faq_a_food_list_languages: "Die eingebaute Lebensmittelliste begann mit israelischen Gerichten und ihren hebräischen Namen. In allen anderen Sprachen erscheint jedes Lebensmittel mit seinem englischen Namen, und die Suche findet jeden englischen Namen, den sie kennt (zum Beispiel findet 'broth' Clear soup); Lebensmittel, die nur einen hebräischen Namen haben, werden dort nicht angezeigt. Alles, was nicht in der Liste steht, kannst du einfach in eigenen Worten schreiben – die KI-Schätzung funktioniert in jeder Sprache.",
    faq_q_food_list_languages: "Warum zeigt die Lebensmittelliste in meiner Sprache englische Namen und weniger Lebensmittel?",
    settings_copyright_line: "© 2026 alle Rechte vorbehalten. App entwickelt von eden zabari.",
    workout_ready_replace_btn: "Ersetzen",
    faq_a_sport_workout_ai: "In „Meine Trainings“ → ⋯ → „Plan mit KI“ (und bei leerer Tabelle auch auf der Kachel neben den fertigen Plänen). Antworte mit wenigen Fingertipps – wie oft pro Woche, wann, Ort, Niveau und Ziel, fast alle auch mit „Sonstiges“ – und füge auf Wunsch eine freie Zeile hinzu, etwa ein empfindliches Knie oder 5 km laufen bis zum Sommer. Die KI erstellt eine ganze Woche: Trainingsarten, Tage, Uhrzeiten, Dauer, Intensität, Übungen und Ruhetage. Vor dem Speichern gibt es eine Vorschau: „In meine Tabelle“ (statt der Tabelle oder zusätzlich), „Anderer Vorschlag“ (bis zu 3-mal) oder „Antworten ändern“. Der Plan ist bewusst moderat, und wenn du Schmerzen oder eine Verletzung erwähnst, bekommst du sanfte Optionen und den Rat, eine Fachperson zu fragen. Er nutzt dasselbe KI-Kontingent wie Zeitplan und Routine: 5-mal kostenlos und 60-mal im Monat mit Premium.",
    faq_q_sport_workout_ai: "Wie erstelle ich einen Trainingsplan mit KI?",
    workout_ai_add: "Zusätzlich zu meiner Tabelle",
    workout_ai_again: "Anderer Vorschlag",
    workout_ai_apply: "In meine Tabelle",
    workout_ai_btn: "Plan mit KI",
    workout_ai_edit: "Antworten ändern",
    workout_ai_failed: "Diesmal kam kein Plan zustande – bitte noch einmal versuchen",
    workout_ai_freq_label: "Wie oft pro Woche",
    workout_ai_freq_ph: "Trainings pro Woche",
    workout_ai_go: "Plan erstellen",
    workout_ai_goal_fitness: "Allgemeine Fitness",
    workout_ai_goal_flexibility: "Beweglichkeit",
    workout_ai_goal_label: "Ziel",
    workout_ai_goal_ph: "Was ist das Ziel?",
    workout_ai_goal_strength: "Kraft",
    workout_ai_goal_weight_loss: "Abnehmen",
    workout_ai_level_advanced: "Fortgeschritten",
    workout_ai_level_beginner: "Einsteiger",
    workout_ai_level_intermediate: "Mittel",
    workout_ai_level_label: "Niveau",
    workout_ai_note_ph: "Etwas Wichtiges? z. B. ein empfindliches Knie oder 5 km laufen bis zum Sommer",
    workout_ai_other: "Sonstiges",
    workout_ai_replace: "Statt meiner Tabelle",
    workout_ai_title: "Trainingsplan mit KI",
    workout_ai_when_evening: "Abends",
    workout_ai_when_label: "Wann",
    workout_ai_when_morning: "Morgens",
    workout_ai_when_noon: "Mittags",
    workout_ai_when_ph: "z. B. nach der Arbeit oder 17:30",
    workout_ai_working: "Dein Plan entsteht…",
    faq_a_sport_workout_jar: "Jede Trainingsart hat ihren eigenen farbigen Stern – Laufen rosa, Gehen grün, Schwimmen blau und so weiter. Jedes Training, das du diese Woche einträgst, aus der Tabelle oder einzeln, lässt seinen Stern ins Glas oben in „Meine Trainings“ fallen, und das Glas füllt sich bis zu deinem Wochenziel (tippe darauf, um das Ziel zu ändern). Ist das Ziel erreicht, leuchtet das Glas. Das kleine Glas daneben zählt, wie viele Wochen in Folge du es gefüllt hast.",
    faq_q_sport_workout_jar: "Was sind die bunten Sterne und das Glas in „Meine Trainings“?",
    faq_a_sport_workout_gcal: "Ja – unter ⋯ → Google Kalender (sobald der Google Kalender in den Einstellungen verbunden ist). Jedes Training mit Uhrzeit wird zu einem Termin, der sich jede Woche an seinen Tagen wiederholt, und Änderungen in der App aktualisieren ihn. Erinnerungen kommen nur aus der App, daher fügt Google keine eigenen hinzu, und die Trainings erscheinen nie doppelt in der App. Ein erneuter Tipp entfernt nur die Trainings aus dem Google Kalender.",
    faq_q_sport_workout_gcal: "Können meine Trainings im Google Kalender erscheinen?",
    workout_gcal_btn: "Google Kalender",
    workout_gcal_error: "Der Google Kalender konnte nicht aktualisiert werden – beim nächsten Ändern klappt es neu",
    workout_gcal_not_connected: "Verbinde zuerst den Google Kalender in den Einstellungen",
    workout_gcal_off_toast: "Die Trainings wurden aus dem Google Kalender entfernt",
    workout_gcal_on_toast: "Deine Trainings sind im Google Kalender",
    faq_a_sport_workout_reminder: "Ja – im Training unter Erinnerung: 10 Minuten, 30 Minuten oder eine Stunde vorher oder eine eigene Zeit (das Training braucht eine Uhrzeit). Sie klingelt wie deine anderen Erinnerungen, einmal und an einem Ort: in der App, wenn sie offen ist, sonst auf deinem Handy. „Erledigt“ trägt das Training in den Verlauf ein, und „Noch nicht“ erinnert in 5 Minuten erneut.",
    faq_q_sport_workout_reminder: "Kann ich vor einem Training erinnert werden?",
    workout_reminder_30min: "30 Minuten vorher",
    workout_reminder_label: "Erinnerung",
    workout_reminder_need_time: "Gib eine Uhrzeit an, um eine Erinnerung zu bekommen",
    faq_a_sport_workout_share: "Unter ⋯ → Teilen wird die Woche zu einem gläsernen Bild in den Farben deines Themes, mit einem dezenten Link zur App (am Handy geht es direkt ins Teilen-Menü, am Computer wird das Bild gespeichert). ⋯ → PDF zum Drucken öffnet eine saubere Seite mit der ganzen Woche und einem Kästchen zum Abhaken neben jedem Training und jeder Übung – wähle „Als PDF speichern“ oder drucke sie aus. Der Plan steht auch im Datenbericht in den Einstellungen, im Teil Sport.",
    faq_q_sport_workout_share: "Wie teile oder drucke ich meine Trainingswoche?",
    share_image_saved: "Das Bild ist gespeichert – du kannst es anhängen",
    share_save_image: "Bild speichern",
    workout_pdf_btn: "PDF zum Drucken",
    workout_share_btn: "Teilen",
    faq_a_sport_workout_board: "Unter ⋯ → Wochenboard ist jeder Tag eine Spalte: Zieh ein Training auf einen anderen Tag (am Handy zuerst lange drücken). In einem Training setzt „Auch in Meiner Routine“ es zu seiner Uhrzeit und an seinen Tagen in deine Routine, und Änderungen bleiben in beide Richtungen gleich; bei einem Eintrag in Meiner Routine macht „Zu meinen Trainings hinzufügen“ das Umgekehrte. Ein ✓ an einer Stelle zählt an beiden, und in „Mein Tag“ erscheint es nur einmal – im Chip neben dem Wasser.",
    faq_q_sport_workout_board: "Wie verschiebe ich ein Training auf einen anderen Tag und verbinde es mit Meiner Routine?",
    routine_in_workouts_btn: "In meinen Trainings öffnen",
    routine_to_workout_btn: "Zu meinen Trainings hinzufügen",
    routine_to_workout_done: "Zu meinen Trainings hinzugefügt 💪",
    workout_delete_confirm_routine: "Es wird aus dem Plan und aus Meiner Routine entfernt. Bereits im Verlauf eingetragene Trainings bleiben.",
    workout_moved: "Verschoben auf {day}",
    workout_routine_need_time: "Gib eine Uhrzeit an, um es in deine Routine zu setzen",
