    workout_view_timeline: "Zeitleiste",
    faq_a_sport_workout_plan: "In der Trainingsverfolgung, unter „Meine Trainings“: + Training – Art, Tage, Uhrzeit, Dauer, Intensität und Ort (auch „Sonstiges“). Kraft-, Funktions- und Schwimmtrainings können eine Übungsliste haben, und „Ruhe“ markiert einen Ruhetag. Du kannst auch mit einem fertigen Plan starten. Das heutige Training steht groß oben, die ganze Woche darunter; ✓ trägt es mit seiner Intensität in den Trainingsverlauf ein. Unter ⋯ legst du ein Wochenziel fest (Trainings oder Minuten) – jedes Training lässt seinen Stern ins Glas fallen.",
    faq_a_sport_workout_today: "In „Mein Tag“ zeigt ein kleiner Chip neben dem Wasser das heutige Training – ein Tipp öffnet Details, ✓ und ▶. ▶ startet einen Timer, der im Chip auf dem Startbildschirm weiterläuft, und „Beenden“ trägt das Training mit der echten Zeit ein. Läuft in New Me die Challenge „Zwei Wochen Bewegung“, zählt ein eingetragenes Training dort von selbst.",
