    faq_a_new_me_magic_themes: "Fünf glitzernde Designs, die zu New Me gehören: Zauberwald, Sternenstaub, Rosenfee, Zauberhaftes Polarlicht und Goldene Dämmerung. Wähle eines in New Me (⚙️ Einstellungen > Farben) oder unter Einstellungen > Aussehen & Anzeige, und ein Glitzerpinsel malt den Bildschirm damit an. Ein magisches Design bringt Glitzer in die ganze App und bei jeder Berührung. Du kannst jederzeit zu jedem anderen Design zurück.",
