    apptour_focus_text: "Alles tritt zur Seite außer der einen Sache für jetzt – mit einem großen ✓. Danach kommt die nächste.",
    apptour_m_presets_text: "Deine gespeicherten Mahlzeiten an einem Ort: Suche, zuletzt verwendet, nach Tageszeit – und ＋ fügt eine zu heute hinzu.",
    apptour_night_text: "🌙 macht die ganze App dunkel, ☀️ holt den Tag zurück.",
    apptour_noteline_text: "Schreib und tippe auf ➤ – es landet in deinen Notizen. 📝 am Anfang wechselt zu 🛒 Einkauf oder 🍎 einer gespeicherten Mahlzeit.",
    apptour_search_text: "Notizen, Einkauf, Kalender, Rezepte, Notizbücher, Ziele, Tabellen und Bücher – eine Suche findet alles.",
    faq_a_new_me_ai_menu: "Vor dem Menü fragt der Fragebogen, welche Mahlzeiten du wann isst (2 Mahlzeiten + ein Snack, 2 Mahlzeiten + ein leichtes Abendessen oder beides), ob du abends noch etwas Kleines isst und um wie viel Uhr, was du nicht isst und wie du Kaffee oder Tee trinkst. Dann erstellt die KI 3 Vorschläge für jede Mahlzeit – jeder so groß wie der Anteil dieser Mahlzeit am Tag, sodass der Tag weiterhin genau 1.300 oder 1.500 ergibt – und Getränkeideen, die als deine festen Getränke gespeichert werden. Wähle pro Mahlzeit bis zu 2 Favoriten; die Vorschläge aus dem ursprünglichen Menü stehen direkt darunter, und unter 🔄 Tauschen kommen sie nach deinem persönlichen Menü. 🔄 Andere Vorschläge erstellt eine neue Runde (3-mal pro Fragebogen). Antworten ändern oder jederzeit ein neues Menü erstellen: ⚙️ Einstellungen → ✨ Persönliches Menü (KI).",
    faq_q_new_me_ai_menu: "Wie funktioniert das persönliche Menü in New Me?",
    nm_ai_menu_building: "Ein Menü für deine Mahlzeiten und Zeiten wird erstellt…",
    nm_ai_menu_drinks: "Getränke für dich",
    nm_ai_menu_error: "Das persönliche Menü konnte gerade nicht erstellt werden – hier ist das ursprüngliche Menü. Du kannst es noch einmal versuchen oder später unter ⚙️ Einstellungen.",
    nm_ai_menu_original: "Aus dem ursprünglichen Menü",
    nm_ai_menu_regen: "Andere Vorschläge",
