    nm_ai_offer_text: "Beantworte ein paar kurze Fragen – wann du isst, was du nicht isst und wie du deinen Kaffee trinkst – und die KI erstellt ein Menü, das zu dir passt. Das ursprüngliche Menü bleibt auch.",
