    apptour_resume: "Dort weitermachen, wo ich aufgehört habe",
    apptour_s_gcal_inside_text: "Verbinde Google Calendar einmal – dann bleiben Termine und Aufgaben in beide Richtungen synchron.",
    apptour_s_menu_text: "Hier findest du alles, was du anpassen kannst – in fünf Gruppen. Schauen wir rein 👇",
    apptour_skip_part: "Diesen Teil überspringen",
    apptour_start: "Tour starten",
    nm_sales_premium: "Enthält das komplette Premium",
    nm_unlock_premium: "Und das komplette Premium ist auch freigeschaltet.",
    settings_sub_status_newme: "Premium ist in deinem New Me enthalten.",
    room_back_to_shelf: "Zum Regal",
    faq_a_new_me_day_total: "Jeder Tag ergibt genau den Plan: die Mahlzeiten, etwa 150 Kalorien für Kaffee und Getränke über den Tag und das, was für den Abend gewählt wurde – etwas Kleines zu essen oder etwas zu trinken. Für den Abend wählst du bis zu 3, die du magst (zum Beispiel eine Banane, einen Joghurt oder 2 Stückchen Zartbitterschokolade; oder Kräutertee, Tee mit etwas Milch oder warme Milch), und ihre Kalorien gehen von den Mahlzeiten ab. Jede Wahl gleicht sich selbst aus: eine kleinere oder größere Option, eine weggelassene Mahlzeit, das kleine Frühstück und die kleine Mahlzeit, die dazugehört, oder der Abend – die Differenz kommt zu den Mahlzeiten dazu oder geht von ihnen ab, jeweils nach ihrer Größe, und unter jeder Mahlzeit steht, wie viel (+ oder −) und was dazu oder weg kann. Eine schon abgehakte Mahlzeit bleibt, wie sie eingetragen wurde. Im Fragebogen zeigt jede Mahlzeit ihre Anpassung, und ein kleiner Kasten zeigt Mahlzeiten, Getränke, den Abend und die Summe. Lust auf etwas anderes an dem Tag? Halte die Summe bei denselben Kalorien oder darunter.",
    faq_q_new_me_day_total: "Wie ergibt ein New-Me-Tag genau 1.300 / 1.500, und wo zählen Getränke?",
