    nm_swap_balanced: "{n} Kalorien verteilt auf die Mahlzeiten, damit der Tag {plan} ergibt",
    books_quotes_chip: "Zitate",
    faq_a_book_quotes: "Im Regal im geheimen Zimmer (Zitate) oder über den kleinen Chip 💬 Zitate in der Leseecke – es ist dieselbe Liste. Tippe auf „+ Zitat“, schreib den Satz und wähle das Buch aus deiner Leseecke oder gib mit „✏️ Sonstiges“ einen anderen Titel ein; der Autor ist optional. ✏️ bearbeitet ein Zitat, 🗑️ löscht es. Die Zitate sind Lesezeichen zum Wischen – 🎨 oben wechselt zu Fotos oder einer Wand aus Karten.",
    faq_a_room_wish_jar: "Im Regal im geheimen Zimmer steht ein Glas für Träume. Tippe auf das kleine Glas im obersten Fach (oder Regal > Das Wunschglas) und schreib, wie dein Leben aussehen soll – so wild du willst, ohne Richtig oder Falsch. Jeder Wunsch wird zu einem Zettel gefaltet und fällt ins Glas. „Einen Zettel ziehen“ öffnet einen zufälligen, und jeder Zettel lässt sich auch einzeln öffnen. Ab dem zweiten Mal, wenn du denselben Wunsch öffnest, kannst du ihn zu einem Ziel machen und in kleine Schritte aufteilen. Einmal pro Woche erscheint sanft ein Zettel mit einem deiner Wünsche – ohne Druck, nur eine Erinnerung, wohin du willst.",
    faq_q_book_quotes: "Wo bewahre ich Zitate aus Büchern auf, die ich geliebt habe?",
    faq_q_room_wish_jar: "Was ist das Wunschglas im geheimen Zimmer?",
