    room_wish_written: "Geschrieben am {date}",
    faq_a_saved_meals_page: "Gespeicherte Mahlzeiten haben eine eigene Seite: Ernährung & Werte > ⭐ Gespeicherte Mahlzeiten (oder ⭐ im Menü). Die Suche oben findet eine Mahlzeit nach Name oder Zutat, „Zuletzt verwendet“ zeigt, was du zuletzt hinzugefügt hast, und die Tabs (Frühstück, Mittagessen, Abendessen, Suppen…) zeigen jede Tageszeit. „+ Heute“ fügt eine Mahlzeit in den heutigen Mahlzeiten-Tracker ein, in den nächsten freien Platz. Tippe auf eine Mahlzeit, um sie zu bearbeiten oder zu löschen, und ＋ oben fügt eine neue hinzu.",
