    presets_tab_snack: "Snacks",
    presets_tab_soup: "Suppen",
    presets_tab_sweet: "Süßes",
    faq_a_notes_sticky_look: "Notizen sind eine kurze Liste aus Glaskarten – 🎨 oben bei den Notizen ändert das Aussehen aller Notizen (die Liste, die Tages-Buttons oben und das Fenster, in dem eine Notiz geschrieben wird): Glas, schlichte Liste, Karteikarten oder Washi-Tape. Eine Notiz, die gerade gezogen wird, behält genau ihr eigenes Aussehen und ihre Farbe. Tippe auf den Text einer Notiz, um sie zu öffnen – dort kannst du sie bearbeiten, ihre Farben ändern und sehen, wann sie zuletzt geschrieben wurde. Tippe auf ○, wenn sie erledigt ist, und × verschiebt sie ins Archiv (🗑️ unten in der Liste holt sie zurück). Zieh sie an ⠿, um die Reihenfolge zu ändern, unter „Später“ oder auf einen Tag oben. ! markiert eine Notiz als dringend – sie gleitet sanft nach oben in die ersten Reihen, mit einem kleinen Tag „Dringend“; ein weiterer Tipp nimmt die Markierung wieder weg.",
    faq_q_notes_sticky_look: "Wie öffne, bearbeite oder entferne ich eine Notiz?",
    note_to_archive_btn: "Ins Archiv verschieben",
    faq_a_routine_clash: "Steht zu dieser Zeit an denselben Tagen schon etwas, gibt es zwei Möglichkeiten: „Ersetzen“ – das Neue bekommt diese Zeit, und für das Bisherige wählst du eine andere Uhrzeit (beim Bearbeiten wird dessen bisherige Zeit vorgeschlagen, sodass die beiden einfach tauschen), oder „Beides“ – beide bleiben zur selben Zeit, eins unter dem anderen. Sind die Tage verschieden (etwa So–Do und Freitag), wird gar nicht gefragt.",
    faq_q_routine_clash: "Was passiert, wenn ich etwas in die Routine zu einer schon belegten Zeit lege?",
    routine_clash_both: "✌️ Beides – beide um {time}",
    routine_clash_move_btn: "Verschieben und speichern",
    routine_clash_move_to: "Auf welche Uhrzeit soll „{title}“?",
    routine_clash_replace: "🔄 Ersetzen – und „{title}“ auf eine andere Zeit verschieben",
    routine_clash_title: "Um {time} steht schon: {title}",
    faq_a_new_me_coffee: "Unter dem heutigen Menü steht eine kurze Übersicht: wie viele Kalorien alle Mahlzeiten des Tages zusammen haben, wie viel für Kaffee und Getränke übrig ist, und Knöpfe für den Kaffee und die Getränke, die du gewählt hast – ein Tippen trägt sie bei den Getränken ein. In „Wähle bis zu 3, die du magst“ unter den Knöpfen (und im Fragebogen) wählst du, was erscheint: Wasser / Sprudel, Kräutertee, ein Light-Getränk, schwarz / Americano (~5), Tee mit etwas Milch (~25), Kaffee mit Wasser und bis zu 100 ml Milch oder Pflanzendrink (~50), leichter Kakao, warme Milch oder normaler Kaffee / Latte (~120).",
    faq_q_new_me_coffee: "Wo trage ich Kaffee ein, und woher weiß ich, wie viel für den Tag übrig ist?",
