    nm_late_ideas: "Zum Beispiel: {ideas}",
    nm_late_ideas_none: "Heute ist nur noch sehr wenig übrig – Tee, Wasser oder schwarzer Kaffee",
    nm_late_room_line: "Etwas Kleines vor dem Schlafen · heute noch ~{n} kcal übrig",
    faq_a_recipe_examples: "Unter deinen eigenen Rezepten findest du Beispielrezepte: Frühstück, Salate, Suppen, Hauptgerichte, Beilagen, Snacks, Desserts und vegane Gerichte, jedes mit Zubereitungszeit, Kalorien pro Portion und wie viel Gramm eine Portion wiegt. Tippe auf ein Rezept, um es zu öffnen; „In Meine Rezepte speichern“ legt deine eigene Kopie an, die du bearbeiten kannst. Die Kategorie-Chips filtern, und ein zweites Tippen auf denselben Chip zeigt wieder alles.",
    faq_a_recipe_grams: "In einem Rezept steht neben den Kalorien „1 Portion ≈ X g“. Bei deinen eigenen Rezepten trägst du im Rezeptformular „Gramm pro Portion“ (und wenn du willst die Zubereitungszeit) ein – beides ist optional, und die Zeit erscheint im Farbband des Rezepts.",
    faq_q_recipe_examples: "Was sind die Beispielrezepte in Meine Rezepte?",
    faq_q_recipe_grams: "Wie sehe ich, wie viel Gramm eine Portion hat?",
    recipe_category_vegan: "Vegan",
    recipe_grams_placeholder: "Gramm pro Portion",
    recipe_meta_grams: "1 Portion ≈ {n} g",
    recipe_meta_grams_short: "{n} g",
    recipe_meta_minutes: "{n} Min.",
    recipe_minutes_placeholder: "Zubereitungszeit (Minuten)",
    recipe_save_example_btn: "In Meine Rezepte speichern",
    recipe_saved_example: "✓ In Meine Rezepte gespeichert",
    recipe_saved_example_toast: "In Meine Rezepte gespeichert – dort kannst du es bearbeiten",
    recipes_examples_title: "Beispielrezepte",
    faq_a_recipe_scan_multi: "Ja. Tippe in „Rezept hinzufügen“ auf 📷 und wähle ein Foto oder mehrere (bis zu 6; ein PDF geht auch). Jedes erscheint in einer kurzen Liste, in der du wählst, was darauf ist: Alles, Zutaten oder Zubereitung, und „➕ Noch ein Foto“ fügt weitere hinzu. Dann tippe auf „✨ Rezept scannen“: Die KI fügt alles zu einem Rezept zusammen, in der richtigen Reihenfolge und ohne doppelte Zeilen, und es zählt als ein einziger Scan. Mehrere Fotos, die du unter 📷 Foto im KI-Assistenten auswählst, öffnen sich ebenfalls hier.",
    faq_q_recipe_scan_multi: "Kann ich ein Rezept aus mehreren Fotos scannen, zum Beispiel Zutaten und Schritte getrennt oder zwei Seiten?",
    recipe_scan_add_more: "➕ Noch ein Foto",
    recipe_scan_part_all: "Alles",
    recipe_scan_part_ingredients: "Zutaten",
    recipe_scan_part_steps: "Zubereitung",
    recipe_scan_remove_photo: "Foto entfernen",
    recipe_scan_run_btn: "✨ Rezept scannen",
    recipe_scan_too_many: "Bis zu {n} Fotos pro Rezept",
    faq_a_note_written_at: "Tippe auf den Text der Notiz, um sie zu öffnen. Darin steht unter dem Text, wann sie zuletzt geschrieben wurde, mit genauem Datum und genauer Uhrzeit. Nur eine Änderung am Text selbst aktualisiert das: Archivieren und Wiederherstellen, Abhaken ✓, Farben oder Verschieben ändern es nicht.",
    faq_q_note_written_at: "Wie sehe ich, wann ich eine Notiz geschrieben habe?",
    note_written_at: "Zuletzt geschrieben: {date}",
    faq_a_new_me_month: "Im Zauberrucksack → Monatskalender: Jeder Tag ist danach eingefärbt, wie viele Mahlzeiten abgehakt wurden, die Pfeile ‹ › wechseln zwischen Monaten, und unter dem Kalender steht der Tagesdurchschnitt der Kalorien im Monat. Ein Tippen auf einen Tag zeigt, wie viele Mahlzeiten abgehakt und wie viele Kalorien an dem Tag gegessen wurden.",
    faq_q_new_me_month: "Wo sehe ich den Monat rückblickend und meine durchschnittlichen Kalorien in New Me?",
    nm_month_avg: "Monatsdurchschnitt: {kcal} Kalorien pro Tag · Tage mit Einträgen: {n}",
    nm_month_day_empty: "An diesem Tag wurde nichts eingetragen.",
    nm_month_day_line: "Abgehakte Mahlzeiten: {checks} · Kalorien: {kcal}",
    nm_extra_line_small: "{n} Kalorien für diese Mahlzeit, vom kleinen Frühstück – z. B. {ideas}",
    faq_a_new_me_small_breakfast: "Ein leichtes Frühstück (etwa 170 kcal): eine Dinkel-Pita (bis 100 kcal) mit Aufstrich oder Käse, dazu etwas Gemüse – wähle bis zu 3, die du magst, zum Beispiel 1 TL Schokoaufstrich, 1 TL Erdnussbutter oder eine Scheibe Schnittkäse (bis 22 %). Weil es klein ist, kommt „Plus eine kleine Mahlzeit“ zu einer anderen Zeit dazu (anderthalb Stunden später, zum Beispiel 11:30 → 13:00 – jede andere Zeit lässt sich wählen): noch eine Pita & Aufstrich, Protein-Joghurt & Obst, Reiswaffeln & Käse, Flocken & Milch oder eine halbe Pita & Eier – bis etwa 200 kcal, mit eigenem ✓. Was dann noch übrig ist, wird auf die anderen Mahlzeiten verteilt, und jede Mahlzeit zeigt, wie viel dazukam – so bleibt die Tagessumme wie im Plan. Du kannst es im Fragebogen wählen oder mit 🔄 nur für heute dazu wechseln – zum Beispiel, wenn das Frühstück spät ist.",
    faq_q_new_me_small_breakfast: "Was ist das „kleine Frühstück“ im New-Me-Menü?",
    home_note_meal_ai: "✨ Mit KI berechnen",
    home_note_meal_none: "Keine gespeicherte Mahlzeit mit diesem Namen",
    myday_earlier: "Früher",
    nm_ing_spelt_pita: "Dinkel-Pitas",
    nm_ing_spread: "Aufstrich (Schoko / Erdnussbutter / rohe Tahini)",
    weather_now: "Draußen gerade: {sky}",
    weather_sky_clear: "Klar",
    weather_sky_clouds: "Bewölkt",
