    weather_sky_rain: "Regen",
    weather_sky_snow: "Schnee",
    weather_sky_storm: "Gewitter",
    faq_a_ai_icon: "Ja – unter Einstellungen > Aussehen & Anzeige. Die weiche Blase ist die Standardeinstellung, und mit Premium kannst du auch ein schwebendes Gehirn oder einen Roboter wählen.",
    faq_a_new_me_favorites: "Ja. Im Fragebogen (und beim Wiederholen über die Einstellungen) kannst du bis zu 2 Optionen pro Mahlzeit wählen. Die erste steht im Menü, darunter eine „oder“-Zeile mit der zweiten – ein Tippen darauf wechselt nur für heute zu ihr. Und wenn das Frühstück nicht rechtzeitig gegessen wurde, verschiebt „⏰ Später“ es auf später am Tag, ohne die Kalorien zu ändern.",
    faq_a_theme_mode: "Manche besonderen Designs sehen dunkel am schönsten aus – Aquarell, Polarlicht, Barbie und die beiden Glitzer-Designs –, deshalb schaltet die Wahl eines davon die App in den dunklen Modus, und jedes andere Design (auch die Rakete) schaltet sie auf hell. Schwarz und Dunkelgrau bleiben dunkel. Danach kannst du jederzeit mit 🌙 im Menü oder mit Heller Modus in den Einstellungen wechseln.",
    faq_a_water_month: "Im Wasser-Tracking. Bei jedem Eintrag im heutigen Protokoll steht die Uhrzeit, zu der er hinzugefügt wurde, und „Monatstabelle“ öffnet den ganzen Monat: Jeder Tag zeigt, wie viele Liter getrunken wurden (✓, wenn das Tagesziel erreicht wurde), und ein Tippen auf einen Tag zeigt seine Einträge mit Uhrzeit.",
    faq_q_ai_icon: "Kann ich das Symbol des KI-Assistenten ändern?",
    faq_q_new_me_favorites: "Kann ich in New Me zwei Lieblingsoptionen für eine Mahlzeit wählen?",
    faq_q_theme_mode: "Warum wurde die App dunkel (oder hell), als ich ein Design gewählt habe?",
    faq_q_water_month: "Wo sehe ich, wie viel Wasser ich an jedem Tag getrunken habe?",
