    nm_times_same_kcal: "Egal, was du wählst – die Kalorien des Tages bleiben gleich: Was wegfällt, wird auf die anderen Mahlzeiten verteilt.",
    dev_sim_panel_title: "PM – nur für dich",
    faq_a_new_me_weight_optional: "Nein. Sowohl das aktuelle als auch das Zielgewicht im Fragebogen sind optional. Wird später ein Wiegen eingetragen (⚖️ Gewicht unter „Meine Reise“ in New Me oder im Gewichtstracker), zählt der Fortschritt ab dem ersten Eintrag.",
    faq_q_new_me_weight_optional: "Muss ich in New Me mein Gewicht angeben?",
    nm_unlock_desc: "Menü, Challenges und die Reise sind bereit – Schritt für Schritt, gemeinsam.",
    nm_unlock_title: "New Me freigeschaltet!",
    room_reveal_star: "Im Teleskop auf dem Dach leuchtet ein neuer Stern ✨",
    faq_a_room_records: "Der Plattenspieler steht von Anfang an im Zimmer, auf dem Baumstumpf neben dem Sessel. Seine Platten öffnen auf YouTube die offiziellen Clips großer Hits der letzten Jahre, und darunter sind fünf ruhige Melodien, die direkt hier im Zimmer spielen – die Platte dreht sich, solange sie laufen, und „⏹ Stopp“ beendet die Musik.",
    faq_a_room_roof_gifts: "Sie kommen mit dem 8. Schlüssel. Ein Antippen des Teleskops lässt dich hindurchschauen: der Nachthimmel ganz nah – zieh (oder nutze die Pfeile), um dich umzuschauen – und deine abgeschlossenen Challenges bilden darin ein Sternbild, ein Stern für jede Challenge; ein Antippen eines Sterns zeigt, welche es war. Ein Antippen der kleinen Truhe öffnet sie – im Moment ist sie leer – und ein weiteres Antippen schließt sie wieder.",
    faq_q_room_records: "Was gibt es auf dem Plattenspieler im geheimen Zimmer?",
    faq_q_room_roof_gifts: "Was sind das Teleskop und die Truhe auf dem Dach?",
    room_chest_letter: "Ein kleiner Brief für dich",
    room_chest_letter_1: "Jeder kleine Schritt auf dem Weg war echt – und jeder einzelne zählt.",
    room_chest_letter_2: "Freundlich zu sich selbst zu sein ist Teil des Weges, keine Pause davon.",
    room_chest_letter_3: "Manche Tage sind leichter, manche schwerer. An beiden da zu sein, ist die wahre Stärke.",
    room_chest_letter_4: "Ausruhen ist erlaubt. Auch Ruhe ist ein Schritt nach vorn.",
    room_chest_letter_5: "Veränderungen, die bleiben, sind die leisen – sie wachsen Tag für Tag.",
    room_chest_letter_6: "Heute ist ein guter Tag, um stolz zu sein – wenn auch nur ein bisschen.",
    room_chest_letter_7: "Es muss nicht alles sein. Nur das nächste kleine Ding.",
    room_chest_letter_8: "Was gestern auch war – heute ist ein neuer Anfang.",
    room_chest_locked: "3 Tage in Folge mit ✓ öffnen die Truhe · {n}/3",
    room_chest_next: "Die Truhe schließt sich wieder – 3 weitere Tage in Folge öffnen sie.",
    room_chest_star: "Ein neuer Stern für deinen Himmel",
    room_chest_sticker: "Ein Sticker für den Deckel",
