    room_pool_ph: "Eine kleine Sache…",
    room_pool_q: "Was würde dein wahres Ich heute tun?",
    room_scope_empty: "Wenn eine Challenge endet, erscheint hier ihr Stern",
    room_scope_hint: "{n} ✦ – jeder Stern ist eine abgeschlossene Challenge",
    room_scope_title: "Deine Challenges in den Sternen",
    room_vinyl_here: "🎻 Ruhige Melodien, direkt hier im Zimmer",
    room_vinyl_yt: "🎬 Die offiziellen Clips auf YouTube",
    dev_sim_buy: "Wie gekauft – sehen, wie sich alles öffnet",
    dev_sim_lock: "Sperren – so sehen wie vor dem Kauf",
    dev_sim_locked_toast: "🔒 Gesperrt – so sieht es vor dem Kauf aus",
    faq_a_new_me_preview: "Ja. Die New-Me-Seite beginnt mit einem kurzen Video davon, was drinnen passiert: der Fragebogen, die Lampen im Flur, der Rucksack, die Challenges und die Schlüssel. Darunter steht alles, was enthalten ist, ein Blick auf einen Tag und kurze Antworten.",
    faq_q_new_me_preview: "Kann ich New Me vor dem Kauf sehen?",
    nm_trailer_c1: "Ein kurzer Fragebogen – und dein Menü ist fertig",
    nm_trailer_c2: "Jede Mahlzeit ist eine Lampe in deinem Flur",
    nm_trailer_c3: "Im Rucksack: das Menü von heute, Wasser und Einkauf",
    nm_trailer_c4: "Eine kleine Challenge geschafft – ein Schlüssel mehr",
    nm_trailer_c5: "Und hinter jeder Tür – etwas nur für dich",
    nm_trailer_end: "Heute geht's los, Schritt für Schritt",
    nm_trailer_label: "🎬 Ein kurzes Video: was in New Me passiert",
    nm_trailer_pause: "Video pausieren",
    nm_trailer_play: "Video abspielen",
    nm_trailer_replay: "Noch einmal ansehen",
    ai_chat_food_edit: "✏️ Kalorien / Protein korrigieren",
    ai_chat_food_invalid: "Kalorien müssen eine Zahl über 0 sein",
    ai_chat_food_updated: "Aktualisiert:",
    faq_a_ai_chat_food_fix: "Ja. Tippe unter der Antwort im Chat auf ✏️ Kalorien / Protein korrigieren, ändere die Zahlen und tippe auf Speichern. Es ändert sich nur, was gerade hinzugefügt wurde – auch wenn es zu einem schon vorhandenen Snack dazukam. KI kann sich irren, ein kurzer Blick lohnt sich.",
    faq_a_new_me_home_btn: "Wenn du New Me hast, öffnet ein kleines 💎 neben dem Fokusmodus oben auf dem Startbildschirm das Menü von heute. Die heutigen Mahlzeiten stehen auch in Mein Tag, jede mit einem ✓.",
    faq_a_routine_item_days: "Ja. Tippe in Meine Routine auf den Punkt und wähle unter 📅 Tage seine Tage – zum Beispiel nur Montag bis Freitag. An den anderen Tagen erscheint er nicht in Mein Tag und hat kein ✓; in Meine Routine bleibt er, blasser, mit seinen Tagen daneben. Die Karte, die nach 3 Tagen ohne ✓ nach einem Punkt fragt, zählt nur seine eigenen Tage.",
    faq_q_ai_chat_food_fix: "Kann ich Kalorien oder Protein korrigieren, nachdem der Assistent Essen eingetragen hat?",
    faq_q_new_me_home_btn: "Wo ist New Me auf dem Startbildschirm?",
    faq_q_routine_item_days: "Kann ein einzelner Punkt in Meine Routine nur an bestimmten Tagen sein?",
    routine_item_days_label: "📅 Tage",
    home_note_meal_ph: "Gespeicherte Mahlzeit suchen…",
    menu_quick_search: "Schnellsuche",
    nm_times_hint: "Tipp: Du kannst die späteste Uhrzeit eintragen, zu der du jede Mahlzeit meist isst – etwa 9:00, wenn du oft gegen 8 isst.",
    room_game_marquee: "Unterwegs – anhalten und genießen",
    room_sand_erase_aria: "Reiben, um die Schrift wegzuwischen",
    faq_a_home_note_line: "Schreib in die Zeile in der Mitte des Startbildschirms und tippe auf ➤ (oder Enter) – sie wird in Notizen gespeichert. Tippe auf 📝 am Anfang der Zeile, und es wird zu 🛒: Dann landet, was du schreibst, auf der Einkaufsliste. Tippe noch einmal für 🍎: Gib ein paar Buchstaben ein, deine passenden gespeicherten Mahlzeiten erscheinen, und ein Tippen trägt eine davon in die heutigen Mahlzeiten ein. Mit 🎤 kannst du es einfach sagen.",
    faq_a_night_mode: "Öffne das Menü ☰ und tippe oben auf 🌙 – die ganze App wird dunkel. ☀️ an derselben Stelle holt den Tag zurück. Das gibt es auch in den Einstellungen, unter „Heller Modus“.",
    faq_q_home_note_line: "Wie schreibe ich eine schnelle Notiz vom Startbildschirm aus?",
    faq_q_night_mode: "Wie wechsle ich in den Nachtmodus?",
    menu_day_mode: "Tagmodus",
    menu_night_mode: "Nachtmodus",
    faq_a_secret_room_yoga: "Am Ende des Waldwegs steht ein leuchtendes Tor, und dahinter, an einem Wasserfall, sitzen die Waldwesen – Lumi, Puffi, Nixie und Sparklet – im Halbkreis auf ihren Matten, und Flora, die Yogalehrerin, sitzt ihnen gegenüber auf der einzelnen Matte auf dem Stein. Tippe auf Flora: Sie öffnet die Augen, alles rückt näher, und das Gespräch beginnt langsam, mit Zeit zum Lesen – Flora fragt, wie es allen geht, jedes Wesen antwortet unter seinem eigenen Namen (mit einem kleinen Bild des sprechenden Wesens neben jeder Zeile), und dann fragt sie dich, wie es sich mit den Menschen anfühlt, die dir nah sind. Das Gespräch geht nach deinen Antworten weiter – gute Menschen, jemand, mit dem es schwer ist, oder sich ein bisschen allein fühlen. Jeder Weg endet mit einer kleinen Mission (sie kann direkt in Mein Tag; wenn die Mission ist, etwas aufzuschreiben, gibt es einen Platz dafür, und es wird im magischen Tagebuch gespeichert) und einer Haltung mit drei Atemzügen gemeinsam. ↩ geht einen Schritt zurück, ✦ startet ein neues Gespräch. Der nächste Schlüssel öffnet den Wasserfall: Wer sich auf den Stein setzt, lässt alles verschwinden, und nur das Rauschen des Wassers bleibt. Wer sich über den Teich beugt, sieht eine Frage aus dem Wasser steigen – was würde dein wahres Ich heute tun? – und die Antwort wird zu einer kleinen Aufgabe in Mein Tag. Es ist ein freundlicher Moment, kein Ersatz für ein Gespräch mit Fachleuten.",
    faq_q_secret_room_yoga: "Was passiert beim Yoga im Wald?",
    room_back_to_forest: "Zurück zum Waldweg",
    room_back_to_yoga: "Zurück zum Yoga",
    room_item_waterfall: "Der Wasserfall",
    room_waterfall_pool_aria: "Das Wasser berühren",
    room_waterfall_rock_aria: "Auf den Felsen setzen",
    room_yoga_guide_aria: "Mit Flora sprechen",
    yg_g_alone: "Danke, dass du das teilst. Das passiert allen manchmal.",
    yg_g_alone_q: "Was würde sich gut anfühlen, auch nur ein bisschen?",
    yg_g_critic: "Kritik kann lange nachstechen. Sie erzählt von einem Moment – nicht vom ganzen Menschen.",
    yg_g_end: "Danke, dass du in den Kreis gekommen bist. Du kannst jederzeit wiederkommen.",
    yg_g_gate: "Du darfst eine Grenze setzen. Eine Grenze ist keine Mauer – sie ist ein Tor.",
    yg_g_good: "Wie schön 💛 Wer hat dir diese Woche gutgetan?",
    yg_g_good_msg: "Guten Menschen darf man das sagen. Ein kleines Danke kann ihnen den ganzen Tag verschönern.",
    yg_g_hard: "Danke, dass du es sagst. Was belastet dich am meisten?",
    yg_g_listen: "Nicht gehört zu werden, ist anstrengend. Deine Stimme zählt, auch wenn sie leise ist.",
    yg_g_new: "Neue Leute beginnen mit einem kleinen Hallo. Ein Kurs, ein Spaziergang, eine Gruppe – ein Schritt.",
    yg_g_old: "Jemand, der dich schon kennt, ist ein warmer Ort. Eine kurze Nachricht reicht.",
    yg_g_start: "Und jetzt zu dir 🌿 Wie fühlt es sich in letzter Zeit mit den Menschen an, die dir nah sind?",
    yg_g_used: "Wenn wir geben und nichts zurückbekommen, wird innen etwas müde. Es ist okay, das zu bemerken.",
