    nm_time_minutes: "Minuten",
    routine_time_taken: "Zu dieser Uhrzeit steht schon etwas: {title}",
    faq_a_new_me_times: "Im Fragebogen am Anfang und jederzeit in den Einstellungen von New Me → „Essenszeiten“. Wenn deine Routine schon Essenszeiten hat, werden sie von dort übernommen – und die Mahlzeiten der Routine lassen sich ausblenden, mit den Mahlzeiten aus New Me an ihrer Stelle. Wenn nicht, wählst du, wie viele Mahlzeiten am Tag (2 Mahlzeiten + ein Snack / 2 Mahlzeiten + ein leichtes Abendessen / 2 Mahlzeiten + ein Snack + ein leichtes Abendessen) und wann jede ist. Bei „2 Mahlzeiten + ein Snack“ sind das Mittagessen um 11:30, ein Snack um 16:00 und Abendessen um 19:00 (jede Zeit lässt sich ändern). Das sind deine Essenszeiten überall: im Flur, in „Mein Tag“, in „Meine Routine“ und in den Erinnerungen. Egal, was du wählst – die Kalorien des Tages bleiben gleich: Was wegfällt, wird auf die anderen Mahlzeiten verteilt.",
    faq_q_new_me_times: "Wie lege ich meine Essenszeiten in New Me fest?",
    nm_times_count: "Wie viele Mahlzeiten am Tag?",
    nm_times_from_routine: "Ja, aus meiner Routine übernehmen",
    nm_times_hide: "Die Mahlzeiten meiner Routine ausblenden und an ihrer Stelle die Mahlzeiten aus New Me zeigen",
    nm_times_later: "Später",
    nm_times_manual: "Nein, hier auswählen",
    nm_times_none_found: "In deiner Routine gibt es noch keine Mahlzeiten – wähle hier, wie viele und wann.",
    nm_times_q: "Hat deine Routine feste Zeiten zum Essen?",
    nm_times_saved: "Essenszeiten gespeichert",
    nm_times_title: "Essenszeiten",
    faq_a_routine_exact_time: "Ja. Wenn du der KI eine Routine mit genauer Uhrzeit beschreibst (wie „16:10 Trading“), wird sie genau so gespeichert – nicht auf die volle Stunde gerundet. Alles, was in deiner Routine steht, erscheint immer auf der Tafel, auch wenn die Stunde in den Stunden-Einstellungen nicht ausgewählt ist, und beim Entfernen einer Stunde, in der etwas steht, wird zuerst nachgefragt. Du kannst eine Uhrzeit auch von Hand ändern: Tippe im Fenster des Eintrags auf die Uhrzeit und wähle Stunde und Minuten.",
    faq_q_routine_exact_time: "Kann meine Routine eine genaue Uhrzeit haben, wie 16:10?",
