    room_vinyl_stop: "⏹ Stopp",
    routine_hour_remove_text: "Was zu dieser Uhrzeit eingetragen ist, wird aus der Routine gelöscht: {title}",
    routine_hour_remove_title: "{time} entfernen?",
    faq_a_routine_ai: "In Meine Routine ⚙️ (oder ➕) öffnen und auf „Eine neue Routine mit KI“ tippen: die Routine in einfachen Worten beschreiben – zum Beispiel „Aufstehen um 7, Sport um 8, Arbeit bis 17“ – und die KI baut einen neuen Tab mit den Uhrzeiten und den Einträgen. Steht im Text, an welchen Tagen („unter der Woche“), öffnet sich der Tab an diesen Tagen, und verschiedene Routinen für verschiedene Tage werden zu eigenen Tabs. Danach lässt sich alles wie gewohnt bearbeiten.",
    faq_a_routine_daysoff: "In Meine Routine auf ➕ und dann auf „Freie Tage“ tippen: die Tage wählen (zum Beispiel Samstag und Sonntag) und die Routine an diesen Tagen – kein Plan (bleibt frei), eine eigene Routine, oder der KI erzählen, was du machst, damit sie sie baut. Freie Tage bekommen einen eigenen Tab, und an diesen Tagen zeigen Meine Routine und Mein Tag nur diesen Tab.",
    faq_q_routine_ai: "Wie erstelle ich eine Routine mit KI?",
    faq_q_routine_daysoff: "Wie lege ich freie Tage in Meine Routine fest?",
