    routine_daysoff_pick_days: "Mindestens einen Tag auswählen",
    routine_daysoff_what: "Und wie sieht die Routine an diesen Tagen aus?",
    routine_daysoff_which: "Welche Tage?",
    faq_a_secret_room_diary: "Nur du. Die Tagebuchseiten werden in deinem Konto gespeichert, sind also auf jedem Gerät da, und niemand sonst kann sie sehen. Geöffnet wird es über das magische Tagebuch auf dem Schreibtisch im geheimen Zimmer und auch über das Tagebuch in der Musikecke. Unter der neuen Seite ist eine zusammengeklappte Monatstabelle: Ein Punkt markiert jeden Tag mit einer Seite, und ein Tippen auf einen Tag öffnet seine Seiten – dort lässt sich eine Seite auch löschen. Sobald das Tagebuch offen ist, kann es auch ins Hauptmenü – mit dem Schalter im Tagebuch selbst oder in den Einstellungen von New Me.",
    faq_a_secret_room_places: "Jeder Eingang am Waldtor öffnet sich mit einem eigenen Schlüssel. Dahinter: die Veranda am Meer (auf dem kleinen Tisch Aladins Wunderlampe – ein Antippen, und ein Waldgeist steigt in einem zauberhaften Nebel daraus auf, wirbelt herum und beginnt ein Gespräch über deinen Wunsch – siehe „Was macht der Geist der Lampe?“), die Gitarre und das Tagebuch (die Gitarre spielt eine kurze, ruhige Melodie und hört von allein auf, und jede der drei Platten, die im Baum hängen, spielt ihre eigene zauberhafte Melodie – ein zweites Antippen stoppt sie –, und ins Tagebuch auf dem Baumstumpf wird geschrieben), der Atemraum (ein stiller See im Sonnenuntergang – auf dem Wasser schwimmt eine Lotuslaterne: antippen, einen Wunsch aufschreiben, und sie treibt mit ihm davon, weit zurück in den See; mit dem Zauberstab kannst du in den Sand schreiben, was du loslassen möchtest, und es bleibt, bis du es mit dem Finger wegwischst) und der Waldweg (er öffnet sich nachts, und Antippen der Laternen wechselt zum Tag; auf der Bank kann man sitzen, und Antippen des Schilds holt es nah heran – eine Tafel mit sechs kleinen Fragen zum Abhaken). An einem verschlossenen Eingang steht, wie viele Schlüssel noch fehlen. Am Ende des Wegs führt ein leuchtendes Tor zum Yoga am Wasserfall – und von dort zum Wasserfall selbst.",
    faq_q_secret_room_diary: "Wer sieht das Tagebuch?",
    faq_q_secret_room_places: "Was ist hinter den Türen im Flur?",
