    ai_chat_working_food: "Einen Moment, ich zähle die Kalorien…",
    ai_chat_working_schedule: "Einen Moment, ich trage es in den Kalender ein…",
    ai_chat_working_table: "Einen Moment, ich erstelle die Tabelle…",
    dev_weather_preview_label: "Vorschau – nur in deinem Konto:",
    faq_a_ai_chat: "Tippe auf die Blase und ein Chat öffnet sich. Wähle, was du tun möchtest – etwas für den Kalender, was du gegessen hast, ein Rezeptfoto oder eine neue Tabelle – oder schreib einfach, und der Assistent erkennt es selbst. Du kannst auch auf 🎙️ tippen und sprechen, statt zu schreiben. Für den Kalender kannst du einmal, jede Woche oder jeden Tag wählen. Die Antwort kommt im Chat, und von dort kannst du mit etwas anderem weitermachen oder den Kalender / dein Essen öffnen.",
    faq_a_new_me_hall: "New Me öffnet sich am Tor eines Zauberwalds, und jeder Eingang darin ist ein Ort: Die runde Tür im Riesenbaum führt ins geheime Zimmer, der hohle Baumstamm zur Veranda am Meer, das Pilzhaus zur Gitarre und zum Tagebuch, der kleine Weidenbogen zum Atemraum, der große Weidenbogen zum Waldweg, und der Blumenbogen mit der Leiter führt hinauf zum Sternendach, sobald es offen ist. An einem verschlossenen Eingang hängt ein Schloss. Auf dem Weg schwebt deine Figur, Sky, und rundherum sind die Spiel-Buttons: die nächste Mission, die Challenge der Woche, der Zauberrucksack mit ganz New Me, die Weltkarte und die Werkzeuge. Ein Tipp auf die Schlüssel oben erklärt, wie man Schlüssel verdient.",
    faq_a_new_me_routine_meals: "Wenn in New Me Mahlzeiten festgelegt sind und Meine Routine auch Mahlzeiten hat, fragt New Me, ob sie ausgeblendet und an ihrer Stelle die New-Me-Mahlzeiten gezeigt werden sollen – damit nichts doppelt erscheint. Meine Routine zeigt dann die New-Me-Mahlzeiten zu ihren Zeiten, mit 💎 und einem ✓; ein Tipp auf den Namen einer Mahlzeit öffnet ein Fenster zur Auswahl einer anderen Mahlzeit oder zum Ändern ihrer Uhrzeit, direkt dort über der Routine. Nichts wird gelöscht: Sie kommen über ⚙️ Einstellungen in New Me → Mahlzeiten in der Routine zurück, oder wenn du „Mit New Me synchronisieren“ im ⚙️ von Meine Routine ausschaltest. Ohne aktives New Me kommen sie von selbst zurück.",
    faq_a_room_computer: "Es ist ein kleiner Chat, der mit „Wie läuft dein Tag bisher?“ beginnt – gut, voll oder schwer – und Schritt für Schritt mit dir weitergeht, bis zu einer kleinen Mission am Ende (die auch direkt in Mein Tag kann). Die Antworten kann man antippen oder frei schreiben – Geschriebenes wird mit der passendsten Antwort verbunden. „↩ Zurück“ geht einen Schritt zurück, um anders zu antworten, und „Neuer Chat“ beginnt jederzeit von vorn. Nach einem vollen oder schweren Tag kannst du später am selben Tag zum Computer zurückkommen: „Ich bin zurück...“ setzt das Gespräch fort. Das grüne Licht unten schaltet den Computer aus und ein. Gespeichert werden nur die Auswahlen, nur auf diesem Gerät und nur bis zum Ende des Tages.",
    faq_q_ai_chat: "Wie spreche ich mit dem Assistenten?",
