    pcx_b3_o1: "Von früh bis spät voll, keine Minute zum Durchatmen",
    pcx_b3_o2: "Nicht wirklich geplant – ich springe von Sache zu Sache, je nachdem, was dringend ist",
    pcx_b3_q: "Das Gefühl, dass der Tag nicht genug Stunden hat, ist unglaublich frustrierend. Wie sieht der Plan von jetzt bis zum Abend aus?",
    pcx_b3a_ask: "Um wie viel Uhr soll diese Pause sein?",
    pcx_b3a_q: "Ohne Pausen durchzurennen ist ein sicheres Rezept für einen Energieabsturz am Abend. Wir brauchen einen geplanten Haltepunkt.",
    pcx_b3a_r1: "Keine Wahl, alles muss erledigt werden",
    pcx_b3a_r2: "Ich versuche, eine Minute freizuschaufeln",
    pcx_b3a_s: "Schon 5 Minuten kompletter Stillstand bringen 50 % der Konzentration zurück.",
    pcx_b3a_t: "Nimm dir jetzt ein großes Glas Wasser und stell dich 3 Minuten ans Fenster oder geh kurz raus – ohne Handy.",
    pcx_b3a_tn: "Anker: Atmen und Wasser",
    pcx_b3b_q: "Im „Feuerwehr“-Modus zu arbeiten steckt viel Energie ins Löschen von Bränden statt ins Vorankommen.",
    pcx_b3b_r1: "Genau, alles wirkt gleich dringend",
    pcx_b3b_s: "Sobald wir 60 Sekunden innehalten und entscheiden, was am wichtigsten ist, hört der Plan auf, uns zu treiben.",
    pcx_b3b_t: "Leg eine feste Endzeit für die Arbeit und Aufgaben von heute fest (etwa 19:00). Was bis dahin erledigt ist – super. Was nicht – wandert auf morgen.",
    pcx_b3b_tn: "Eine Grenze setzen",
    pcx_b_end1: "Wir haben super gearbeitet. Gut zu wissen: Selbst an einem vollen Tag bringt dich ein kleiner Schritt zurück ans Steuer.",
    pcx_b_end2: "Einen ruhigen, fokussierten restlichen Tag! Und wenn es später zu viel wird – ich bin da. Komm einfach zurück, und wir reden darüber.",
    pcx_b_o1: "Zu viele Aufgaben und endlose Listen",
    pcx_b_o2: "Eine Flut von Gedanken, Sorgen und Lärm im Kopf",
    pcx_b_o3: "Keine Zeit – als würde ich im Kreis rennen",
    pcx_b_q: "Total verständlich. Volle Tage fühlen sich manchmal an wie ein Rennen ohne Ziellinie. Welche Art von Last drückt gerade am meisten?",
