    pcx_back_hi: "Hallo, schön, dich wiederzusehen 💛",
    pcx_back_resume: "↩ Zurück zu unserem Gespräch",
    pcx_br1_q: "Überraschungen und Änderungen in letzter Minute sind das Frustrierendste. Es fühlt sich an, als wäre alles, was wir aufgebaut haben, durcheinandergeraten. Die neue Aufgabe, die reingekommen ist – muss sie wirklich jetzt sofort passieren?",
