    pcx_br1_s1: "Okay, Geduld. Wenn sie alles andere verdrängt, ist das Vorherige offiziell bis morgen eingefroren. Ohne schlechtes Gewissen.",
    pcx_br1_s2: "Super. Wir setzen sie auf die „Morgen“-Liste und lassen nicht zu, dass sie die Ruhe des Abends stiehlt.",
    pcx_br1_t: "Entscheide jetzt gleich eine einzige Sache, die heute vom Tisch ist, um Platz zu schaffen.",
    pcx_br1_tn: "Der kompromisslose Filter",
    pcx_br2_q: "Das ist das Natürlichste der Welt. Mitten in verrücktem Druck kostet selbst eine Pause Kraft. Kein Grund, dir böse zu sein.",
    pcx_br2_r1: "Stimmt, ich bin einfach weitergerannt und jetzt ist die Luft raus",
    pcx_br2_s: "Wenn der Akku leer ist, helfen jetzt weder Fokus noch Willenskraft. Dein Körper sagt ganz klar, dass er auftanken muss.",
    pcx_br2_t: "10 Minuten kompletter Stillstand: Wasser trinken, kaltes Wasser ins Gesicht und 3 Minuten sitzen, ohne auf einen Bildschirm zu schauen.",
    pcx_br2_tn: "Schneller Neustart",
    pcx_br3_q: "Nach Stunden ununterbrochener Arbeit schaltet das Gehirn ins „Notfallprotokoll“, und die Leistung fällt stark ab. Es jetzt zu erzwingen, dauert einfach dreimal so lange.",
    pcx_br3_r1: "Genau, derselbe Satz zieht 4-mal an meinen Augen vorbei",
    pcx_br3_s: "Das ist das klare Signal des Gehirns: „Ich mache für heute den Laden dicht.“",
    pcx_br3_t: "Statt gegen die Müdigkeit zu kämpfen – schließ den Tag jetzt ab: Schreib die ersten 2 Aufgaben für morgen früh auf, schließ die Tabs oder den Computer und wechsle offiziell in den Abendmodus.",
    pcx_br3_tn: "Bewusst abschließen",
    pcx_br_me: "Hallo, ich bin zurück... immer noch zu viel / es ist schwerer geworden",
    pcx_br_o1: "Mehr Aufgaben und Chaos, die ich nicht eingeplant hatte",
    pcx_br_o2: "Ich habe nicht geschafft, was wir geplant hatten, und meine Energie ist im Keller",
