    pcx_br_q: "Wie schön, dass du zurückgekommen bist. Toll, dass du kurz angehalten hast, statt auf Autopilot weiterzurennen. Was ist seit unserem Gespräch passiert?",
    pcx_break_title: "Pause mit Wasser und Atmen 🌬️",
    pcx_breath_done: "Schön. 5 Atemzüge – dein Körper weiß schon, wie er sich beruhigt. 💛",
    pcx_breath_in: "Einatmen...",
    pcx_breath_out: "Ausatmen...",
    pcx_c1_o1: "Schlafmangel / die Augen fallen zu",
    pcx_c1_o2: "Angespannter Körper / steife Schultern / schwerer Kopf",
    pcx_c1_q: "Wenn der Körper müde oder ausgelaugt ist, fühlt sich jede kleine Aufgabe wie eine Bergbesteigung an. Wo zeigt sich diese Müdigkeit gerade?",
    pcx_c1a_q: "Nichts raubt Energie und Stimmung so sehr wie Schlafmangel. Gibt es eine Möglichkeit, einen Gang runterzuschalten oder etwas Warmes zu trinken?",
    pcx_c1a_r1: "Ich muss weiterarbeiten",
    pcx_c1a_r2: "Ich kann langsamer machen",
    pcx_c1a_s: "Wenn du mit großer Müdigkeit unterwegs bist, sollte das, was du von dir erwartest, aufs absolute Minimum sinken.",
    pcx_c1a_t: "Wenn möglich – 15 Minuten mit geschlossenen Augen. Wenn nicht – kaltes Wasser ins Gesicht und ein großes Glas Wasser, um wieder etwas Luft zu bekommen.",
    pcx_c1a_tn: "Powernap oder kaltes Wasser",
    pcx_c1b_q: "Emotionaler Stress sammelt sich oft direkt im Körper und in den Muskeln. Ein bisschen Entspannung hilft, die Flammen zu senken.",
    pcx_c1b_r1: "Der Druck zeigt sich wirklich in meinem Körper",
    pcx_c1b_s: "Sobald der Körper die Last loslässt, bekommt der Kopf das Signal, dass alles okay ist.",
    pcx_c1b_t: "Lass die Schultern sinken, atme 3-mal tief in den Bauch und roll den Nacken langsam.",
    pcx_c1b_tn: "Lockerungs-Dehnung",
    pcx_c2_o1: "Das Gefühl, nicht verstanden / unfair behandelt zu werden",
    pcx_c2_o2: "Wut, die noch kocht",
    pcx_c2_q: "Reibereien oder schwierige Gespräche mit Menschen hinterlassen einen schweren Nachgeschmack, der die Ruhe eines ganzen Tages ruinieren kann. Was stört dich daran am meisten?",
    pcx_c2a_q: "Sich nicht gesehen oder nicht verstanden zu fühlen, ist unglaublich frustrierend. Magst du es hier in Worte fassen?",
    pcx_c2a_r1: "Ja, das ist passiert...",
    pcx_c2a_r2: "Nein, ich habe keine Lust, darin herumzuwühlen",
    pcx_c2a_s: "Völlig berechtigt. Manchmal ist es der gesündeste Schritt, es für einen Moment beiseitezulegen.",
    pcx_c2a_t: "Erinnere dich daran, dass die Deutung anderer nicht die absolute Wahrheit ist – und schick diesen Groll bis morgen in die Pause.",
    pcx_c2a_tn: "Emotionale Grenze",
    pcx_c2b_q: "Wut ist starke Energie, die raus muss, sonst frisst sie uns von innen auf.",
    pcx_c2b_r1: "Ich will die Wut einfach rauslassen",
    pcx_c2b_s: "Dann lassen wir sie sicher raus, ohne dir zu schaden.",
    pcx_c2b_t: "Box in ein Kissen, mach einen zügigen 5-Minuten-Spaziergang oder schreib die ganze Wut auf ein Blatt – und zerreiß es.",
    pcx_c2b_tn: "Körperliches Ablassen",
    pcx_c3_o1: "Chaos im Zeitplan / eine Panne bei etwas, das ewig gedauert hat",
    pcx_c3_o2: "Das Gefühl zu versagen / etwas, woran ich gearbeitet habe, hat nicht geklappt",
    pcx_c3_q: "An Tagen, an denen alles schiefgeht, fühlt man sich hilflos. Was ist heute vor allem schiefgelaufen?",
    pcx_c3a_q: "Wenn die Dinge außerhalb unserer Kontrolle liegen, gilt nur eine Regel: in den „leichten Überlebensmodus“ wechseln. Was kann für heute abgesagt werden?",
    pcx_c3a_r1: "Ich habe einiges abgesagt, aber es ist immer noch Druck da",
    pcx_c3a_s: "Erwartungen zu senken ist kein Aufgeben – das ist Alltagsweisheit.",
    pcx_c3a_t: "Such dir eine Aufgabe für heute aus und lass sie offiziell los, um etwas Luft zu schaffen.",
    pcx_c3a_tn: "Einen Gang runterschalten",
    pcx_c3b_q: "Enttäuschung tut weh, besonders nach viel Mühe. Aber ein Versuch, der nicht geklappt hat, ist nur eine Information – keine Definition davon, wer wir sind.",
    pcx_c3b_r1: "Es zieht mich immer noch sehr runter",
    pcx_c3b_s: "Es ist okay, sich niedergeschlagen zu fühlen. Gib dem Raum, ohne dich zu kritisieren.",
    pcx_c3b_t: "Tu jetzt gleich eine kleine tröstende Sache (ein warmes Getränk, ein Lieblingslied).",
    pcx_c3b_tn: "Selbstmitgefühl",
    pcx_c4_o1: "Ruhig, ohne mit zu vielen Leuten zu reden",
    pcx_c4_o2: "Auf der Suche nach etwas Kleinem, das mich tröstet oder aufbaut",
    pcx_c4_q: "Auch das hat seinen vollen Platz. Du musst nicht immer erklären, warum, um dir etwas Mitgefühl und Ruhe zu gönnen. Wie möchtest du den Rest des Tages verbringen?",
    pcx_c4a_s: "Ruhe ist ein großartiges Ladegerät. Du darfst heute ein bisschen Abstand nehmen.",
    pcx_c4a_t: "Schalte dein Handy für die nächste Stunde auf lautlos oder „Nicht stören“.",
    pcx_c4a_tn: "Die Blase",
    pcx_c4b_s: "Kleine Dinge machen an grauen Tagen einen großen Unterschied.",
    pcx_c4b_t: "Such dir für heute Abend eine schöne Sache aus (ein guter Film, eine heiße Dusche, ein leckeres Essen).",
    pcx_c4b_tn: "Ein kleiner Genuss",
    pcx_c_end1: "Gut zu wissen: Ein schwerer Tag ist kein schweres Leben – nur eine Seite in einem ganzen Buch. Morgen ist ein neuer Tag.",
    pcx_c_end2: "Einen ruhigen, sanften Abend. Und wenn du noch mehr loswerden musst oder es später schwer wird – ich bin da. Komm einfach zurück, und wir reden.",
    pcx_c_o1: "Körperlich mies / wahnsinnig müde",
    pcx_c_o2: "Etwas Unangenehmes mit jemandem / ein Streit / eine Kränkung",
    pcx_c_o3: "Alles geht schief / Pläne sind komplett geplatzt",
    pcx_c_o4: "Einfach ein schweres Gefühl, ohne klaren Grund",
    pcx_c_q: "Oh, das tut mir leid zu hören... solche Tage können uns wirklich auslaugen. Ein Tag darf so sein, und das ist völlig okay. Magst du erzählen, was dich heute am meisten belastet?",
    pcx_cr1_s: "Es ist völlig okay, dass es nicht mit einem Zauberstab verschwunden ist. Solche Tage muss man einfach mit minimalem Aufwand durchstehen. Kämpf nicht gegen das Gefühl an – lass diesen Tag einfach ruhig enden.",
    pcx_cr2_o1: "🌬️ 5 Atemzüge zusammen",
    pcx_cr2_o2: "✍️ 3 Sätze schreiben",
    pcx_cr2_s: "Wenn der Kopf überläuft, hilft es am besten, den Fokus auf den Körper zu lenken. Wir können zusammen 5 langsame Atemzüge machen, oder du schreibst hier 3 Sätze über alles, was dir durch den Kopf geht – um es rauszulassen.",
    pcx_cr3_s: "Es wird ganz sicher gut. Du hast schon schwierige Tage durchgestanden, und auch dieser Tag ist gleich vorbei. Du hast heute dein Bestes gegeben, und das ist völlig genug. Eine Umarmung! 🤗",
