    dictation_btn_aria: "Sprechen und es wird geschrieben",
    dictation_mic_denied: "Das Mikrofon ist blockiert – erlaube es über das 🔒 neben der Adresse im Browser oder in den Telefoneinstellungen",
    faq_a_dictation: "Ja – tippe auf das Mikrofon 🎤 in der Ecke der schnellen Notiz oder einer Schreibseite im Heft und sprich: Die Wörter werden beim Sprechen geschrieben, in der Sprache der App. Noch einmal tippen beendet es. Beim ersten Mal fragt der Browser nach der Erlaubnis für das Mikrofon. Funktioniert in Chrome / Android und in Safari auf dem iPhone. Am Computer brauchst du ein Mikrofon und einen Browser wie Chrome, Edge oder Safari – fehlt etwas, sagt die Meldung genau, was.",
    faq_q_dictation: "Kann ich sprechen statt tippen?",
    faq_a_secret_room: "Ein Raum nur für dich, in New Me – ein Haus im Inneren eines Riesenbaums. Du siehst immer eine Wand und drehst dich mit den Pfeilen (oder per Wischen). Der erste Schlüssel kommt nach einem ✓ bei einer Mahlzeit an 3 verschiedenen Tagen und öffnet die Tür – und mit ihr den ganzen Raum: den Computer, das Spiel, den Plattenspieler, das Regal mit der Bibliothek darin und die Katze. Danach gibt jede abgeschlossene Challenge (auch die Challenge der Woche) einen Schlüssel, der den nächsten Ort öffnet: das Sternendach, die Veranda am Meer, die Gitarre und das Tagebuch, den Atemraum, den Waldweg mit Yoga, den Wasserfall und eine Überraschung auf dem Dach – und die 8. bringt eine Flasche aus dem Meer, mit dem Brief aus der Vergangenheit darin. Wenn sich etwas öffnet, zeigt ein Pfeil den Weg dorthin. Auch die kleine Tür unten am Spielautomaten öffnet sich – vorerst ist das Schränkchen dahinter leer. Auf dem Sternendach fällt ein angetippter Stern wie eine Sternschnuppe, und die Katze sitzt auf dem Kissen.",
