    room_wall_board_hint: "Ein Zettel öffnet sich beim Antippen · jede beendete Challenge = ein Schlüssel",
    room_wall_board_title: "Die Zielwand",
    room_wall_game_hint: "Ein Spiel für eine Minute · jeder Schlüssel füllt ein Puzzleteil im Fenster",
