    room_wall_shelf_hint: "Bücher, Hefte und Erinnerungen · die Tür führt aufs Dach",
    room_wall_shelf_title: "Das Regal und die nächste Tür",
    room_wall_window_hint: "Tippe auf einen Gegenstand, um näherzukommen · die Pfeile drehen das Zimmer",
    room_wall_window_title: "Das Fenster und der Computer",
    faq_a_steps_in_sport: "Oben in der Trainingsverfolgung, in einem kleinen Streifen: die Schritte von heute und von dieser Woche. Die Schritte werden automatisch gezählt, sobald sich die App in der Handy-Version mit Google Fit / Apple Health verbindet – der 🔗-Knopf daneben erklärt es.",
    faq_q_steps_in_sport: "Wo ist der tägliche Schrittzähler?",
    sport_steps_today_label: "Schritte heute",
    sport_steps_week_label: "diese Woche",
    faq_a_reminders_one_place: "Jede Erinnerung kommt einmal und an einem Ort. Ist die App gerade vor dir geöffnet (auf dem Computer, dem iPad oder dem Handy), erscheint sie dort; sonst kommt sie als Benachrichtigung nur aufs Handy. '✅ Erledigt, danke!' oder 'Verstanden!' an irgendeinem Ort schließt sie auf allen Geräten, und sie kommt nicht wieder. 'Noch nicht' verschiebt sie: Sie kommt alle 5 Minuten wieder, jedes Mal an einem Ort. Die Aufgabe in der Liste mit ✓ abzuhaken zählt ebenfalls als erledigt. Um die Benachrichtigungen auch auf Computer und Tablet zu bekommen, schalte 'Auch auf Computer und Tablet' unter Einstellungen > Benachrichtigungen ein.",
    faq_q_reminders_one_place: "Warum kommt eine Erinnerung nur einmal und nur aufs Handy?",
    reminder_all_devices_hint: "Standardmäßig kommt jede Erinnerung einmal und an einem Ort: aufs Handy oder auf das Gerät, auf dem die App gerade vor dir geöffnet ist. Erledigt oder Verstanden an einem Ort schließt sie überall.",
    reminder_all_devices_label: "Auch auf Computer und Tablet",
    myday_water_info: "8 mittlere / kleine Gläser Wasser sind im Schnitt etwa 2 Liter",
    faq_a_good_things: "Am Abend (ab 18 Uhr) erscheint unter dem Datum ein kleiner Knopf: Schreib bis zu 3 schöne Dinge auf, die heute passiert sind – schon eins reicht. Sie werden gespeichert, und unter „Vorige Tage“ siehst du, was du früher geschrieben hast. „Heute nicht“ blendet ihn bis morgen aus, und ganz ausschalten kannst du ihn unter Einstellungen > Personalisierung & Kalender.",
    faq_a_home_countdown: "Markiere einen Termin im Kalender mit ⭐ (der Stern daneben in der Terminliste). Der nächste markierte Termin in den kommenden 100 Tagen erscheint unter dem Datum – „Noch 3 Tage · Mamas Geburtstag“, „Morgen · …“ oder „Heute · …“. Tippe darauf, um im Kalender zu diesem Tag zu springen.",
    faq_a_home_streak: "Es zählt, an wie vielen Tagen in Folge du mindestens ein ✓ hattest – egal ob in Mein Tag, Meine Routine, Meine Ziele oder New Me. Es erscheint ab 2 Tagen. Gibt es heute noch kein ✓, ist die Serie nicht gerissen – der ganze Tag liegt noch vor dir. Und wenn sie endet, verschwindet sie einfach still, ganz ohne schlechtes Gewissen.",
    faq_a_home_weather: "Schalte „Wetter im Himmel des Startbildschirms“ unter Einstellungen > Personalisierung & Kalender ein und erlaube den Standort. Dann zeigt der Himmel des Startbildschirms das echte Wetter bei dir – Sonne (oder nachts Mond und Sterne), Wolken, Regen, Schnee, Gewitter oder Nebel – in jedem Design, etwa alle 40 Minuten aktualisiert. Dein ungefährer Standort (auf etwa 1 km gerundet) bleibt nur auf deinem Gerät und wird über unseren Server bei MET Norway abgefragt. Standardmäßig ist es aus. Unter dem Schalter steht, wie das Wetter gerade draußen ist – zum Beispiel ⛅ Teilweise bewölkt, deshalb zeigt der Himmel Sonne und Wolken zugleich.",
    faq_q_good_things: "Was ist „3 schöne Dinge von heute“?",
    faq_q_home_countdown: "Wie bekomme ich einen Countdown auf den Startbildschirm?",
    faq_q_home_streak: "Was ist das 🔥 „Tage in Folge“ unter der Begrüßung?",
    faq_q_home_weather: "Wie bekomme ich das Wetter in den Himmel des Startbildschirms?",
    good_things_chip: "3 schöne Dinge von heute",
    good_things_chip_done: "3 schöne Dinge ✓",
    good_things_hint: "Etwas Kleines, das heute schön war – schon eins reicht.",
    good_things_past: "Vorige Tage",
    good_things_past_empty: "Vorige Tage erscheinen hier.",
    good_things_placeholder: "Etwas Schönes, das passiert ist…",
    good_things_saved_toast: "Gespeichert. Gute Nacht 🌙",
    good_things_skip: "Heute nicht",
    good_things_title: "3 schöne Dinge von heute",
    home_countdown_days: "Noch {n} Tage · {title}",
    home_countdown_today: "Heute · {title}",
    home_countdown_tomorrow: "Morgen · {title}",
    home_streak_days: "{n} Tage in Folge",
    home_streak_title: "Tage in Folge mit mindestens einem ✓",
    settings_good_things_label: "„3 schöne Dinge“ am Abend",
    settings_weather_hint: "Regen, Wolken oder Schnee im Hintergrund des Startbildschirms, je nach Wetter bei dir. Dein ungefährer Standort bleibt auf diesem Gerät und wird über unseren Server bei MET Norway abgefragt.",
    settings_weather_label: "Wetter im Himmel des Startbildschirms",
    weather_failed: "Das Wetter konnte gerade nicht abgerufen werden.",
    weather_location_denied: "Kein Zugriff auf den Standort – erlaube ihn in den Browser-Einstellungen und versuch es noch einmal.",
    faq_a_home_focus: "Tippe oben auf dem Startbildschirm auf ◎: Alles verschwindet bis auf das eine Ding für jetzt – was in dieser Stunde dran ist oder das Nächste auf der Liste für heute – mit einem großen ✓ und der schnellen Notiz. Nach dem ✓ erscheint das Nächste. „Fokusmodus ✕“ oben holt alles zurück.",
    faq_a_home_search: "Öffne das Menü ☰ – die Suche steht ganz oben. Tippe mindestens 2 Buchstaben: Die Ergebnisse kommen aus deinen Notizen, der Einkaufsliste, dem Kalender, Rezepten, Heften (Titel und Seitentext), Zielen, Tabellen und Büchern, nach Art sortiert – tippe auf eines, um direkt dorthin zu springen.",
    faq_a_my_day: "„Mein Tag“ bringt das frühere „Ein Blick auf Heute“ und „Meine Routine“ auf einer Zeitleiste zusammen. Unten auf dem Startbildschirm siehst du, wie viel erledigt ist, was jetzt oder als Nächstes dran ist (mit schnellem ✓) und neben dem Titel ein Glas Wasser per +1. Tippe darauf (oder wische nach oben), um den ganzen Tag zu öffnen: oben, was keine Uhrzeit hat, dann alles nach Stunden – Aufgaben, Ereignisse und Termine aus dem Kalender, feste Wochentermine, die heutige Routine, die kleinen Schritte deiner Ziele und New-Me-Mahlzeiten – mit einer Linie für jetzt. Filtere nach Aufgaben, Routine oder Terminen & Treffen. Ein ✓ hier ist dasselbe ✓ überall sonst (Meine Routine, Meine Ziele, Kalender) und öffnet ein Gänseblümchen in der Ecke. „Routine bearbeiten“ öffnet „Meine Routine“ (auch im Menü), und „＋ Für heute hinzufügen“ legt eine Aufgabe für heute an. Ein Tippen auf den Titel „Mein Tag“ (oder auf den kleinen Balken oben) schließt es wieder.",
    faq_q_home_focus: "Was ist der Fokusmodus?",
    faq_q_home_search: "Wie suche ich in der ganzen App?",
    faq_q_my_day: "Was steckt in „Mein Tag“ unten auf dem Startbildschirm?",
