    faq_a_new_me_tour: "Direkt nach dem Kauf und dem kurzen Fragebogen zeigt eine kurze Tour das Spiel: die obere Leiste, die nächste Mission, die Challenge der Woche, den Zauberrucksack und Tür 1 zum geheimen Zimmer. Sie lässt sich jederzeit unter ⚙️ Einstellungen > 🧭 New Me-Tour wiederholen – dort kann auch der vollständige Name aus dem Fragebogen geändert werden. Vor dem Kauf zeigt New Me im Menü ein 🔒, und ein Tipp darauf öffnet eine Seite mit allem, was enthalten ist.",
