    nm_letter_gift_title: "Der Brief aus der Vergangenheit",
    nm_gift_locked_view: "Das Geschenk öffnet sich nach allen {n} Challenges – noch {left}.",
    nm_gift_intro: "Alle {n} Challenges, Schritt für Schritt. Das hat gewartet:",
    nm_gift_title: "Dein Geschenk",
    faq_a_new_me_letter_gift: "Zu Beginn von New Me (oder später unter Challenges) kann ein Brief an dich in der Zukunft geschrieben werden. Einmal versiegelt, lässt er sich weder lesen noch bearbeiten, bis er sich öffnet: in der Flasche aus dem Meer im geheimen Zimmer oder am Ende aller 20 Challenges – und dort wartet auch ein Geschenk.",
    faq_q_new_me_letter_gift: "Was ist der Brief aus der Vergangenheit?",
    faq_a_new_me_challenges: "🏆 Challenges bietet 20 Challenges: 10 große (z. B. 5 Tage ohne Zucker, eine Woche ohne Kohlenhydrate oder 4 kg in einem Monat abnehmen – jeden Tag Kaloriendefizit, Training und kein Zucker) und 10 Mini-Challenges – kleine Gewohnheiten für eine Woche, wie Zimtkaffee ohne Zucker. Bei der Wahl einer Challenge wird gefragt, wann es losgeht: heute, morgen, nächste Woche oder an einem anderen Datum. Eine große und eine Mini-Challenge können gleichzeitig laufen. Die laufende Challenge steht oben im Menü und in Mein Tag, mit einem ✓ für den Tag. Jede Challenge-Woche bringt einen freien Tag (🍕), der sie nicht unterbricht, und ein nicht abgehakter Tag zählt als freier Tag – heute und gestern können abgehakt werden. Manche Tage haken sich selbst ab: ein 20-Minuten-Training in der Trainingsverfolgung oder die Menü-Mahlzeiten mit ✓. Jede Challenge hat ein ⓘ mit dem, was genau zählt (zum Beispiel die ganze Liste der Kohlenhydrate) – in der Challenge selbst und daneben in Mein Tag. Darunter bietet 🌱 Persönliche Entwicklung 48 kleine Challenges für eine Woche (sie zählen nicht zu den 20) – siehe „Was ist die Challenge der Woche?“.",
    faq_q_new_me_challenges: "Wie funktionieren die Challenges in New Me?",
    nm_letter_too_short: "Noch ein paar Worte 🙂",
    nm_letter_quiz_note: "Freiwillig – er kann auch später unter Challenges geschrieben werden.",
    nm_letter_write: "✍️ Brief schreiben",
    nm_letter_sealed_line: "Versiegelt am {date} · öffnet sich nach den {n} Challenges",
    nm_letter_sealed_toast: "Versiegelt ✉️ – wir sehen uns im Ziel",
    nm_letter_seal_note: "Einmal versiegelt, kann der Brief bis zum Ende aller Challenges weder gelesen noch bearbeitet werden.",
    nm_letter_seal: "✉️ Brief versiegeln",
    nm_letter_ph: "Wo ich heute stehe, wohin ich will, was mir beim Essen schwerfällt, was ich mir im Ziel sagen möchte…",
    nm_letter_intro: "Jetzt geschrieben und versiegelt – er öffnet sich erst nach allen {n} Challenges, um zu sehen, wie viel sich seitdem verändert hat. Wo stehe ich jetzt? Was sind meine Ziele, und was fällt mir beim Essen schwer?",
