    nm_ch_lose5_month_desc: "Drei Dinge jeden Tag: im Kalorienbudget bleiben (Defizit), ein Training und kein zugesetzter Zucker. Es zählen die Tage – nicht die Waage, die ihr eigenes Tempo hat.",
