    nm_ch_menu_21_title: "21 Tage nach Menü",
    nm_ch_no_sugar_21_desc: "Drei Wochen ohne zugesetzten Zucker – genug Zeit, damit sich die Gelüste beruhigen. Obst und natürliche Süße sind willkommen.",
