    nm_ch_gift_left: "noch {n}",
    nm_ch_gift_locked: "Am Ende wartet ein Geschenk",
    nm_ch_completed_label: "Challenges geschafft",
    nm_tile_challenges: "Challenges",
    faq_a_workout_calories: "Ja. Jedes Training bekommt eine Schätzung der verbrannten Kalorien – nach Art, Dauer und deinem letzten Gewicht (beim Laufen und Radfahren auch nach Tempo, wenn eine Strecke eingetragen ist). Sie erscheint in der Trainingsliste und in der Monatsübersicht (Verbrannt) und kommt zum Kalorienbudget dieses Tages dazu: im Täglichen Mahlzeiten-Tracker, in den Kalorien- und Gewichtswerten und im Ring von New Me. Es ist eine Schätzung, darum steht ein ~ davor.",
    faq_q_workout_calories: "Zählen Trainings zu meinen Tageskalorien?",
    faq_a_new_me_flexible_menu: "Ja. Im Fragebogen und in den Einstellungen wählst du, wie viele Mahlzeiten am Tag – 2 Mahlzeiten + ein Snack / 2 Mahlzeiten + ein leichtes Abendessen / 2 Mahlzeiten + ein Snack + ein leichtes Abendessen –, und ➖ auf einer Mahlzeitenkarte entfernt sie (mindestens 3 bleiben); „➕ Wieder aufnehmen“ holt sie zurück. So oder so bleiben die Kalorien des Tages gleich: Was wegfällt, wird auf die anderen Mahlzeiten verteilt, und unter jeder Mahlzeit steht, wie viel dazukam und was passen würde. ✏️ Bearbeiten öffnet den Text einer Mahlzeit – ändere, was du willst (z. B. ohne Brot oder mit einem Ei mehr), und die KI berechnet Kalorien und Eiweiß neu. 🔄 Tauschen bietet Optionen aus dem Menü, ⭐ Gespeicherte und ✨ Schreiben; jede Änderung kann nur für heute oder ab jetzt gelten. Und am Ende von „Der ganze Tag“ gibt es ➕ Essen hinzufügen – schreib, was außerhalb des Menüs gegessen wurde, und die KI berechnet es und fügt es zu heute hinzu (✕ löscht es).",
    faq_q_new_me_flexible_menu: "Kann ich in New Me die Zahl der Mahlzeiten ändern oder eine eigene Mahlzeit essen?",
    daily_calorie_mini_burn: "+🔥 {amount} vom Training",
    calorie_burn_line: "🏃 {amount} kcal vom Training – zum Tagesbudget dazu ({budget})",
    sport_total_kcal: "Verbrannt",
    nm_swap_ai_too_big: "Etwas mehr, als für heute übrig ist – bis ~{n} kcal passen. Du kannst es trotzdem eintragen – die restlichen Mahlzeiten des Tages werden zum Ausgleich kleiner – oder eine kleinere Portion wählen.",
