    apptour_g_card_text: "Tippe auf eine Karte, um sie umzudrehen: Meilensteine zum Abhaken (📅 trägt einen Meilenstein in den Kalender ein), warum es wichtig ist, und die Belohnung. Die Labels zeigen die restlichen Tage und ob du im Plan bist.",
    apptour_g_card_title: "Eine Zielkarte",
    apptour_g_focus_text: "Das eine Ziel, auf das du dich diesen Monat konzentrierst: Es erscheint ganz oben, mit einem Weg zum Pokal, und auch in „Mein Tag“. Tippe bei einem beliebigen Ziel auf 🎯, um es auszuwählen (Premium).",
