    vision_focus_ribbon: "🎯 Ziel des Monats",
    vision_tagline: "Große Ziele, kleine Schritte.",
    faq_a_app_tour: "Die Tour öffnet sich einmal automatisch, beim ersten Öffnen. Sie beginnt mit ihren Teilen – tippe auf einen, um direkt dorthin zu springen – und zeigt dann alle Teile der App (den Startbildschirm, den KI-Assistenten und jeden Menüpunkt) und die fünf Gruppen der Einstellungen, jeweils mit einer kurzen Erklärung, und schaut bei einigen hinein (zum Beispiel ein Beispiel-Zielpfad, die Tasche und Google Calendar). Weiter geht vorwärts, Zurück geht zurück, Diesen Teil überspringen springt zum nächsten Teil und ✕ schließt die Tour. Du kannst sie jederzeit unter Einstellungen > Hilfe & Nutzung > App-Tour wiederholen und dort weitermachen, wo du aufgehört hast. Weiter und Zurück bleiben immer an derselben Stelle unten auf dem Bildschirm, und am Computer funktionieren auch die Pfeiltasten.",
    faq_q_app_tour: "Wie sehe ich mir die App-Tour noch einmal an?",
    apptour_done_text: "Noch Fragen? Hilfe & FAQ in den Einstellungen beantwortet alles, und diese Tour findest du jederzeit unter Hilfe & Nutzung.",
    apptour_done_title: "Das war's! 🎉",
    apptour_flow_recurring: "Ratenzahlungen & Daueraufträge",
