    apptour_s_support_text: "Hilfe & FAQ, Kontakt, App teilen – und diese Tour, jederzeit.",
    apptour_s_account_text: "Premium, Passwort, ein persönlicher PDF-Bericht, Synchronisierung mit Google Calendar und Kontolöschung.",
    apptour_s_notifications_text: "Erinnerungsbenachrichtigungen und ihr Ton. '⏰ Noch nicht' bei einer Erinnerung funktioniert wie die Schlummertaste beim Wecker: Alle 5 Minuten wirst du erneut erinnert.",
    apptour_s_personalization_text: "Land, Mahlzeiten und Snacks pro Tag, wann dein Finanzmonat beginnt und was auf dem Startbildschirm erscheint.",
    apptour_s_appearance_text: "Sprache, heller oder dunkler Modus, Designs, Schriftart, Textfarbe, Barrierefreiheit und App-Größe.",
    apptour_m_style_text: "Diese Schaltfläche stellt das Menü auf große Kacheln um – und zurück. Auf dem Startbildschirm erscheint nur eine der beiden.",
    apptour_m_style_title: "Liste oder Kacheln",
