    apptour_m_calories_link: "Auch das Gewichts-Tracking ist hier – geteilt mit New Me und mit Gewichtszielen in „Meine Ziele“.",
    apptour_m_calories_text: "Tägliche, wöchentliche und monatliche Kalorienstatistiken im Vergleich zu deinen Zielen.",
    apptour_m_meals_link: "Gespeicherte Mahlzeiten, eine Lebensmittelliste und KI-Schätzungen; New Me, Schnelleinträge und Getränke zählen hier auch.",
    apptour_m_meals_text: "Trag jede Mahlzeit mit Kalorien und Eiweiß ein, Tag für Tag.",
    apptour_m_recipes_link: "Scanne ein geschriebenes Rezept mit 📷 Foto im KI-Assistenten.",
    apptour_m_recipes_text: "Deine Rezepte nach Kategorie, mit Fotos, Kalorien und Portionen.",
    apptour_m_goal_link: "Kann automatisch dein Gewicht oder erledigte Aufgaben verfolgen.",
    apptour_m_goal_text: "Ein Ziel für den Monat, mit Fortschrittsbalken und einer Belohnung, wenn du es erreichst.",
    apptour_m_shopping_link: "Füge Artikel in Sekundenschnelle über Schnelle Notiz hinzu.",
    apptour_m_shopping_text: "Deine Einkaufsliste – hake Artikel im Laden ab.",
    apptour_m_notes_link: "Zieh eine Notiz auf Heute, Morgen oder Anderes Datum, um sie zur Aufgabe zu machen; gelöschte Notizen warten im Archiv 🗑️.",
    apptour_m_notes_text: "Notizen und Ideen in einer Liste.",
    apptour_m_tables_link: "Der KI-Assistent kann automatisch eine Tabelle entwerfen.",
    apptour_m_tables_text: "Persönliche Tabellen – Geschenke, Serien, Listen – mit Spalten für Text, Zahl, Auswahl, Datum und ✓ (Premium).",
    apptour_m_study_link: "🪄 Intelligente Aufteilung in der Karte ✅ Aufgaben zerlegt eine große Aufgabe in Schritte in deinem Kalender.",
    apptour_m_study_text: "Deine Tasche: ein Fach für jeden Lebensbereich – mit Heften, Tabellen und Aufgaben darin.",
    apptour_m_vision_link: "📅 bei einem Meilenstein trägt ihn in den Kalender ein; kleine Schritte und die Aufgaben einer Tage-Challenge erscheinen in „Mein Tag“, und der Fortschritt kann auch einer Zahl oder deinem Gewicht folgen.",
    apptour_m_vision_text: "Deine Ziele als Wege aus kleinen Schritten – mit den Schritten von heute ganz oben. Schauen wir hinein 👇",
    apptour_m_myweek_link: "Synchronisiert sich mit Google Calendar (in den Einstellungen).",
    apptour_m_myweek_text: "Der Monatskalender, wiederkehrende Wochenaufgaben mit Erinnerungen und alle deine Termine mit Datum. Dazu ein Papierkalender mit den Treffen der Woche 🤝.",
    apptour_m_newme_link: "Alles zählt in „Täglicher Mahlzeiten-Tracker“ und „Mein Tag“; das Gewicht wird mit „Kalorien- und Gewichtswerte“ geteilt.",
    apptour_m_newme_text: "Ein Ernährungsplan mit 1.300 / 1.500 Kalorien in einer magischen Spielwelt: das heutige Menü mit ✓, Tausch auf drei Arten – aus dem Menü, aus deinen gespeicherten Mahlzeiten oder indem du der KI schreibst, was du gegessen hast, und sie berechnet die Kalorien – eine Einkaufsliste, Erinnerungen an Mahlzeiten und eine Fortschrittsreise mit Erfolgen, Körpermaßen und Fotos. Dazu 🏆 20 Challenges – mit einem Geschenk am Ende – und eine Challenge der Woche.",
    apptour_ai_table_text: "Beschreibe die Tabelle, die du brauchst – die KI entwirft ihre Spalten (Premium).",
    apptour_ai_photo_link: "Wird in Meine Rezepte gespeichert.",
    apptour_ai_photo_text: "Fotografiere ein geschriebenes Rezept – die KI legt ein neues Rezept für dich an.",
    apptour_ai_schedule_link: "Sie erscheinen im Kalender und in „Mein Tag“.",
    apptour_ai_schedule_text: "Beschreibe Pläne in einfachen Worten, einmalig oder wiederkehrend – sie landen direkt im Kalender.",
    apptour_ai_food_link: "Landet direkt in „Täglicher Mahlzeiten-Tracker“ und in der heutigen Summe.",
    apptour_ai_food_text: "Gib ein, was du gegessen hast – die Kalorien werden für dich geschätzt und eingetragen.",
    apptour_newme_short_text: "Öffnet New Me – das heutige Menü steht direkt auf dem Hauptbildschirm.",
    apptour_ai_link: "Eine kleine 1 darauf ist die tägliche Erinnerung „Was heute wichtig ist“.",
    apptour_ai_text: "Schreib in einfachen Worten, dein Assistent macht den Rest: Er erfasst Kalorien, trägt Pläne in den Kalender ein, liest ein Rezept aus einem Foto und baut Tabellen.",
    apptour_quicknote_link: "📝 und 🛒 öffnen die vollständigen Listen; 🍎 trägt eine gespeicherte Mahlzeit in „Täglicher Mahlzeiten-Tracker“ ein.",
    apptour_quicknote_text: "Schreib schnell etwas auf – in deine Notizen oder direkt auf die Einkaufsliste.",
    apptour_routine_link: "Eine Gewohnheit kann automatisch ein Training in der Trainingsverfolgung eintragen.",
    apptour_routine_text: "Deine Tagesroutine nach Uhrzeit, in Tabs (Kinder, Lernen, Arbeit…). Hake jeden Tag ✓ ab, um Gewohnheiten und Serien aufzubauen; 📅 zeigt den ganzen Monat.",
    apptour_premium_text: "Schaltet den vollen KI-Assistenten, Designs, Schriftarten, Meine Tasche und mehr frei.",
    apptour_note_text: "Ein Haftzettel für die ganze Woche. Darin fügt das Zahnrad ⚙ eine Checkliste mit 1–3 Zeilen hinzu und ändert Farbe und Stil.",
    apptour_peek_link: "Hier erscheinen Aufgaben von der KI, aus dem Kalender und aus Google Calendar sowie Meilensteine deiner Ziele – dazu die heutigen Kalorien 🔥 und dein 🎯 Ziel des Monats.",
    apptour_peek_text: "Alles von heute an einem Ort – Aufgaben, Termine, deine Routine und kleine Schritte auf einer Zeitleiste. Hake ✓ direkt hier ab.",
