    finance_category_new_option: "➕ Neue Kategorie…",
    menu_switch_to_list: "Zur Listenansicht",
    menu_switch_to_tiles: "Zur Kachelansicht",
    faq_a_receipts_total: "Auf dem Bildschirm Rechnungen / Belege auf 🧮 'Summe aller Belege' tippen. Den Zeitraum von Jahr bis Jahr wählen (standardmäßig vom ältesten Beleg bis zu diesem Jahr), auf Berechnen tippen, und es erscheint die Summe beider Kategorien zusammen - Haushaltsausgaben und Geschäftsausgaben - sowie die Anzahl der Belege und die Summe jeder Kategorie einzeln.",
    faq_q_receipts_total: "Wie lassen sich alle Belege eines Zeitraums addieren?",
    receipts_total_empty: "Keine Belege in diesen Jahren.",
    receipts_total_invalid: "Bitte einen gültigen Jahresbereich eingeben",
    receipts_total_count: "Belege: {count}",
    receipts_total_calc_btn: "Berechnen",
    receipts_total_to_year: "Bis Jahr",
    receipts_total_from_year: "Von Jahr",
    receipts_total_title: "Summe aller Belege",
    receipts_total_tile: "Summe aller Belege",
    faq_a_quick_note_apple: "Der 🍎 neben 📝 und 🛒 im Notizfenster ist ein Kurzbefehl, um schnell eine deiner gespeicherten Mahlzeiten für heute im Bereich „Täglicher Mahlzeiten-Tracker“ einzutragen. Er ist standardmäßig aktiviert - wenn du ihn nicht brauchst, schalte ihn unter Einstellungen > Personalisierung & Kalender aus ('🍎-Kurzbefehl für gespeicherte Mahlzeiten im Notizfenster anzeigen') und dort jederzeit wieder ein.",
    faq_q_quick_note_apple: "Was ist der 🍎 im Notizfenster, und kann ich ihn ausblenden?",
    settings_quick_note_apple_label: "🍎-Kurzbefehl für gespeicherte Mahlzeiten im Notizfenster anzeigen",
    faq_a_vision_board_today: "Tippe in „Meine Ziele“ unter dem Weg eines Ziels (im „Plan“) neben einem Meilenstein auf 📅 und wähle ein Datum. Du kannst auch „🔁 Jede Woche, bis es erledigt ist“ einschalten – dann kommt er jede Woche am selben Tag wieder, bis du ihn einmal abhakst. Der Meilenstein erscheint an diesem Tag in „Mein Tag“ und im Kalender (und in Google Calendar, falls verbunden), und der Button zeigt, wann er geplant ist. Ein ✓ an einer Stelle hakt ihn auch an der anderen ab und bringt den Weg des Ziels voran. Tippe erneut auf 📅, um das Datum zu ändern oder ihn aus dem Kalender zu entfernen. Löschst du eine einmalige Aufgabe aus dem Kalender, wird auch der Meilenstein aus dem Ziel gelöscht; löschst du eine Woche einer wöchentlichen Erinnerung, wird nur diese Woche entfernt.",
    faq_q_vision_board_today: "Wie trage ich einen Meilenstein eines Ziels in den Kalender ein (📅)?",
    vision_milestone_already_today: "Dieser Meilenstein ist bereits in den heutigen Aufgaben.",
    auth_consent_required: "Für die Registrierung ist die Zustimmung zu den Nutzungsbedingungen und zur Datenschutzerklärung erforderlich.",
    auth_consent_privacy: "Datenschutzerklärung",
