    nm_drinks_total: "{n} / ~{kcal} kcal",
    nm_drink_missing: "Gib einen Getränkenamen und die Kalorien ein",
    nm_drink_more: "+ Weiteres Getränk",
    nm_drink_add: "Hinzufügen",
    nm_drink_name_ph: "Getränk (z. B. Saft)",
    nm_drinks_hint: "Gib einfach das Getränk ein – die Kalorien werden automatisch berechnet, und die Zahl lässt sich ändern.",
    nm_slot_drinks: "Getränke",
    faq_a_new_me_tracking: "Tippe oben in New Me auf die nächste Mission und dann auf ✓ Gegessen, um die nächste Mahlzeit als gegessen zu markieren – das ganze Menü mit ✓ für jede Mahlzeit gibt es in „Der ganze Tag“ an der Seite, und die heutigen Mahlzeiten erscheinen auch in Mein Tag auf dem Startbildschirm – tippst du dort auf eine (oder fährst mit der Maus darüber), siehst du genau, was es zu essen gibt, mit ✓ und Tauschen. Alles ist mit dem Täglichen Mahlzeiten-Tracker synchronisiert: Mahlzeiten aus dem Plan, Getränke und alles, was du woanders hinzufügst (zum Beispiel ein Kaffee über das Schnell-Hinzufügen), werden in New Me und in Mein Tag zusammen gezählt – nichts, was du schon eingegeben hast, wird überschrieben, und das Entfernen eines ✓ entfernt nur den New Me-Teil. Wenn alle Mahlzeiten des Tages abgehakt sind, gibt es eine kleine Feier. Unter „Getränke“ trägst du die Getränke des Tages ein – zusammen bis zu ~150 kcal, also etwa 3 Getränke mit je bis zu ~50 kcal. Tipp einfach den Namen des Getränks ein, und die Kalorien werden automatisch per KI ausgefüllt. Die beiden Kaffee/Tee-Zeilen haben außerdem ein Feld „Milch? Wie viel?“ (zum Beispiel „ein bisschen“ oder „50 ml“), und die Berechnung wird aktualisiert; die Zahl lässt sich vor dem Hinzufügen und auch danach ändern. Ein Getränk mit Namen und Kalorien wird automatisch gespeichert, sobald du weitermachst – auf Hinzufügen zu tippen ist optional. Tippe auf ☆ neben einem Getränk, um es als Stammgetränk zu speichern – Stammgetränke erscheinen als Buttons oben auf der Getränke-Karte, und ein Tipp fügt sie dem Tag hinzu. ⭐ speichert eine Mahlzeit als gespeicherte Mahlzeit. „Tagestabelle“ zeigt, was du gegessen hast, mit Kalorien und Protein. Das kleine 💎 neben dem Fokusmodus oben auf dem Startbildschirm öffnet es direkt. Kalorien- und Proteinwerte sind KI-Schätzungen und können Fehler enthalten. Nicht alles gegessen? Unter einer abgehakten Mahlzeit zieht „Nicht alles gegessen?“ ein Viertel, die Hälfte oder drei Viertel der Portion ab – oder das, was du aufschreibst, berechnet – und die Kalorien des Tages werden aktualisiert.",
    faq_q_new_me_tracking: "Wie funktionieren ✓, Tauschen und Kalorien in New Me?",
    faq_a_new_me_what: "New Me ist ein eigenes Tagesmenü-Programm mit zwei fertigen Plänen – 1.300 oder 1.500 Kalorien – aus 2 Hauptmahlzeiten und 2 Snacks, mit je 3 Optionen. Es enthält das komplette Premium. Preis: $11.99 im Monat (jederzeit kündbar) oder einmalig $99.99, lebenslang. Geöffnet wird es über 💎 New Me im Menü. Vor dem Start gibt es einen kurzen Fragebogen, der mit einem medizinischen Hinweis beginnt, der bestätigt werden muss. Das Programm ist nur eine allgemeine Information und ersetzt keine Ärztin, keinen Arzt und keine klinische Ernährungsberatung.",
    faq_q_new_me_what: "Was ist New Me und wie bekomme ich es?",
