    auth_password_placeholder_login: "Passwort",
    routine_overview_no_checks: "In diesem Monat noch nichts abgehakt - tippe an den Tagen, an denen du deine Routine-Einträge erledigst, auf das ✓ daneben.",
    faq_a_finance_cycle_day: "Standardmäßig wird deine Budgetübersicht am 1. jedes Kalendermonats zurückgesetzt. Wenn dein Gehalt an einem anderen Tag kommt (z. B. am 10.), stell hier stattdessen diesen Tag ein - deine Monatsübersicht, dein Verlauf und dein Zielbudget laufen dann von diesem Tag bis zum selben Tag im Folgemonat, statt vom 1. bis zum Monatsende.",
    faq_q_finance_cycle_day: "Was bewirkt die Einstellung 'Tag für den Monatsbudget-Neustart'?",
    faq_a_quick_note_view_full_lists: "Im Menü ☰ findest du Notizen und Einkaufsliste direkt. Im Fenster Schnelle Notiz (im Fokusmodus) führen auch die kleinen 📝 und 🛒 neben Hinzufügen dorthin, und 🍎 trägt schnell eine deiner gespeicherten Mahlzeiten ein.",
    faq_q_quick_note_view_full_lists: "Wie sehe ich aus Schnelle Notiz meine vollständigen Notizen oder meine Einkaufsliste?",
    note_triage_otherdate: "Anderes Datum", note_triage_otherdate_modal_title: "Datum auswählen", note_triage_otherdate_missing: "Bitte wähle ein Datum", note_triage_success_otherdate: "Zu deinem Kalender hinzugefügt!", notes_ai_placeholder_shopping: "Zur Liste hinzufügen",
    daily_greeting_morning: "Guten Morgen!", daily_greeting_afternoon: "Guten Tag!", daily_greeting_evening: "Guten Abend!", daily_greeting_night: "Gute Nacht!", calorie_monthly_view_title: "Monatsansicht", calorie_monthly_avg_label: "Tagesdurchschnitt:", calorie_monthly_avg_empty: "Diesen Monat noch keine Daten erfasst", calorie_monthly_day_total_label: "Tagesgesamt:", notes_ai_added_shopping: "Zur Einkaufsliste hinzugefügt", quick_note_dest_notes: "📝 Notizen", quick_note_dest_shopping: "🛒 Einkaufsliste",
    faq_q_calorie_monthly_view: "Wie sehe ich meinen Kalorienverlauf für einen ganzen Monat?", faq_a_calorie_monthly_view: "Die Kalorienmetriken haben eine 'Monatsansicht'-Karte mit einem Kalender - jeder Tag, an dem du Essen erfasst hast, bekommt einen Punkt, und der Tagesdurchschnitt dieses Monats wird über dem Raster angezeigt. Tippe auf einen beliebigen Tag, um genau zu sehen, was du gegessen hast und die Gesamtsumme. Dieselbe Aufschlüsselung ist auch enthalten, wenn du deinen persönlichen Bericht (PDF) in den Einstellungen herunterlädst, sofern der Bereich Kalorienmetriken angehakt ist.",
    faq_q_calorie_stats_total_vs_average: "Sind die Wochen-/Monatszahlen bei den Kalorienmetriken eine Summe oder ein Durchschnitt?", faq_a_calorie_stats_total_vs_average: "Beides - die große Zahl ist die Summe (Gesamtsumme) von allem, was in der aktuellen Kalenderwoche/im aktuellen Kalendermonat erfasst wurde, und die kleine Zeile darunter ist der Tagesdurchschnitt. Der Durchschnitt wird nur durch die Tage geteilt, an denen du wirklich etwas erfasst hast, nicht durch 7 oder den ganzen Monat - ein Tag ganz ohne Eintrag wird einfach übersprungen, er zählt nicht als 0 und drückt den Durchschnitt nicht nach unten.",
    faq_q_weight_note: "Kann ich einer Gewichtseintragung eine Notiz hinzufügen?", faq_a_weight_note: "Ja - neben den Gewichts-/Datumsfeldern bei der Regelmäßigen Gewichtsverfolgung (zu finden ganz unten in Ernährung & Werte > Kalorien- und Gewichtswerte, bei ⚖️) gibt es ein optionales Notizfeld. Nutze es für Kontext wie „nach dem Training\" oder „Morgenwiegen\" - sie wird neben diesem Eintrag in der Verlaufsliste angezeigt.",
    faq_q_quick_note_shopping_list: "Kann Schnelle Notiz direkt auf meine Einkaufsliste schreiben?", faq_a_quick_note_shopping_list: "Ja – tippe in der Schreibzeile in der Mitte des Startbildschirms auf das 📝 am Anfang: Es wird zu 🛒, und was du schreibst, kommt direkt auf die Einkaufsliste, ohne Umweg über Notizen.",
