    nutrition_daily_tracker_title: "Täglicher Mahlzeiten-Tracker", nutrition_copy_yesterday_btn: "Menü von gestern kopieren",
    nutrition_daily_tile_title: "Ernährungs-Tipps",
    nutrition_daily_masthead_title: "📰 THE NUTRITION DAILY", nutrition_daily_masthead_subtitle: "Dein tägliches Magazin für Ernährung, Präzision und Lebensstil",
    nutrition_daily_article1_title: "📰 Das Waagen-Rätsel – Wann wiegt man was?",
    nutrition_daily_article1_intro: "Die empfohlenste und genaueste Methode zur Verfolgung ist, dein Essen vor dem Kochen zu wiegen (im rohen Zustand) - von Fleisch bis Reis, Pasta, Kartoffeln und Gemüse.",
    nutrition_daily_article1_why: "Warum vor dem Kochen? Rohes Essen hat feste Werte. Kochen verändert nur den Flüssigkeitsgehalt des Essens (Wasseraufnahme oder -verdunstung), sodass du durch vorheriges Wiegen beliebig kochen kannst, und sogar Zutaten mischen kannst (wie bei Frikadellen oder Eintöpfen), ohne die Genauigkeit zu verlieren.",
    nutrition_daily_article1_portion_tip: "Portionstipp: Schon den ganzen Topf im Voraus gewogen und berechnet? Das Gewicht des gekochten Essens spielt keine Rolle mehr! Du kannst das fertige Gericht einfach gleichmäßig nach der geplanten Portionsanzahl aufteilen.",
    nutrition_daily_article1_after_note: "Wiegst du lieber nach dem Kochen? Wenn dein Lebensstil komplexer ist und Wiegen auf dem Teller nach der Zubereitung erfordert - auch das funktioniert super! Achte nur darauf, in der Datenbank die dafür vorgesehene Option zu wählen (wie \"gekochter weißer Reis\" statt \"trockener Reis\"). 💡",
    nutrition_daily_article2_title: "📰 Tagesziel überschritten? Kein Stress!",
    nutrition_daily_article2_body: "Ziel überschritten? Beim Zunehmen etwas zu wenig gegessen, oder beim Abnehmen etwas zu viel? Atme durch - alles in Ordnung. Dein Körper ist kein täglicher Rechner - er funktioniert mit einem wöchentlichen Durchschnitt über die Zeit. Ein Ausreißertag ist ein völlig natürlicher Teil des Prozesses. Es besteht keine Notwendigkeit, es \"auszugleichen\", zu hungern oder sich bei der nächsten Mahlzeit zu zwingen. Setze einfach deine normale Routine fort. Beständigkeit über die Zeit ist das eigentliche Geheimnis.",
    nutrition_daily_article3_title: "📰 Auswärts essen? So protokollierst du wie ein Profi",
    nutrition_daily_article3_intro: "Restaurants, Pizzerien und Burgerläden sind immer ein schönes Erlebnis - aber wie erfasst du ein Gericht, das du nicht selbst zubereitet hast?",
    nutrition_daily_article3_breakdown: "Die Zerlegungsmethode: Zerlege das Gericht in seine Grundbestandteile (z.B. Nudeln + Hähnchenbrust + ein Esslöffel Öl + Sauce).",
    nutrition_daily_article3_estimate: "Die Schätzmethode: Nicht sicher? Suche in der Lebensmitteldatenbank nach einem ähnlichen Gericht für eine solide Durchschnittsschätzung.",
    nutrition_daily_article3_control: "Volle Kontrolle: Maximale Genauigkeit gewünscht? Bereite die Mahlzeit zu Hause aus deinen genauen Zutaten zu, und speichere sie als voreingestellte Mahlzeit in der App! 🎯",
    meal_photo_scan_title: "Essensfoto scannen (Premium)", meal_photo_scan_btn: "Essensfoto scannen (Premium)", meal_photo_loading_text: "Analysiere dein Essen...",
